RAW.push(...[
{"q":"Theo chủ nghĩa duy vật lịch sử, nhân tố quyết định sự tồn tại và phát triển của xã hội loài người là gì?","o":["Hoàn cảnh địa lý tự nhiên","Hoạt động sản xuất tinh thần","Sản xuất vật chất","Sự gia tăng dân số"],"a":[2],"e":"Giáo trình khẳng định sản xuất vật chất là cơ sở của sự tồn tại và phát triển xã hội: nó tạo ra tư liệu sinh hoạt, tư liệu sản xuất và là «hành vi lịch sử đầu tiên» của con người. Mọi hoạt động khác (chính trị, khoa học, nghệ thuật…) đều dựa trên nền tảng này.","w":["Hoàn cảnh địa lý là một yếu tố của tồn tại xã hội, có thể làm sản xuất nhanh hay chậm nhưng không quyết định sự phát triển xã hội.","Sản xuất tinh thần dựa trên sản xuất vật chất, không phải nhân tố quyết định.","","Dân số là điều kiện thường xuyên của sản xuất, ảnh hưởng nhưng không quyết định sự phát triển xã hội."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.1 (Sản xuất vật chất là cơ sở của sự tồn tại và phát triển xã hội)","c":5,"v":"khớp","id":"dv-I.1","p":1,"t":"Trắc nghiệm"},
{"q":"Phương thức sản xuất là sự thống nhất giữa:","o":["Lực lượng sản xuất và kiến trúc thượng tầng tương ứng","Cơ sở hạ tầng và kiến trúc thượng tầng của xã hội","Người lao động và tư liệu sản xuất trong một xã hội","Lực lượng sản xuất và quan hệ sản xuất tương ứng"],"a":[3],"e":"Phương thức sản xuất là sự thống nhất giữa lực lượng sản xuất ở một trình độ nhất định với quan hệ sản xuất tương ứng. Lực lượng sản xuất là mặt kỹ thuật (người ↔ tự nhiên), quan hệ sản xuất là mặt kinh tế (người ↔ người).","w":["Kiến trúc thượng tầng không thuộc phương thức sản xuất; nó dựng trên cơ sở hạ tầng.","Cơ sở hạ tầng + kiến trúc thượng tầng là kết cấu của hình thái kinh tế - xã hội (cùng với lực lượng sản xuất), không phải phương thức sản xuất.","Người lao động + tư liệu sản xuất chỉ hợp thành lực lượng sản xuất, mới là một mặt của phương thức sản xuất.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.1 (Sản xuất vật chất là cơ sở của sự tồn tại và phát triển xã hội)","c":5,"v":"khớp","id":"dv-I.2","p":1,"t":"Trắc nghiệm"},
{"q":"Lực lượng sản xuất bao gồm:","o":["Người lao động và tư liệu sản xuất","Tư liệu lao động và đối tượng lao động","Quan hệ sở hữu, quản lý và phân phối","Công cụ lao động và phương tiện lao động"],"a":[0],"e":"Lực lượng sản xuất là sự kết hợp giữa người lao động với tư liệu sản xuất, tạo ra sức sản xuất và năng lực thực tiễn cải biến tự nhiên. Tư liệu sản xuất gồm tư liệu lao động (công cụ, phương tiện) và đối tượng lao động.","w":["","Tư liệu lao động + đối tượng lao động mới chỉ là tư liệu sản xuất, thiếu yếu tố người lao động.","Sở hữu, quản lý, phân phối là ba mặt của quan hệ sản xuất, không phải lực lượng sản xuất.","Công cụ và phương tiện lao động chỉ là tư liệu lao động, một bộ phận nhỏ của lực lượng sản xuất."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-I.3","p":1,"t":"Trắc nghiệm"},
{"q":"Trong các yếu tố của lực lượng sản xuất, yếu tố giữ vai trò quyết định là:","o":["Công cụ lao động","Người lao động","Đối tượng lao động","Khoa học và công nghệ"],"a":[1],"e":"Người lao động là chủ thể sáng tạo, sử dụng và cải tiến tư liệu sản xuất nên là nhân tố quyết định của lực lượng sản xuất. Bẫy hay gặp: công cụ lao động là yếu tố «động nhất, cách mạng nhất», còn người lao động là yếu tố «quyết định».","w":["Công cụ lao động là yếu tố động nhất, cách mạng nhất, không phải yếu tố quyết định.","","Đối tượng lao động chỉ là bộ phận của tư liệu sản xuất, chịu tác động của người lao động.","Khoa học ngày nay trở thành lực lượng sản xuất trực tiếp, nhưng nó vẫn phải thông qua người lao động và công cụ; không phải yếu tố quyết định."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-I.4","p":1,"t":"Trắc nghiệm"},
{"q":"Yếu tố động nhất, cách mạng nhất trong lực lượng sản xuất là:","o":["Công cụ lao động","Người lao động","Đối tượng lao động","Nguyên liệu sản xuất"],"a":[0],"e":"Giáo trình viết: «Công cụ lao động là yếu tố động nhất, cách mạng nhất trong lực lượng sản xuất», luôn được cải tiến và là thước đo trình độ chinh phục tự nhiên, tiêu chí phân biệt các thời đại kinh tế.","w":["","Người lao động là yếu tố quyết định. (Lưu ý: ở mục quần chúng nhân dân, giáo trình có câu gọi quần chúng lao động là «yếu tố động nhất», nhưng khi hỏi các yếu tố của lực lượng sản xuất thì đáp án chuẩn là công cụ lao động.)","Đối tượng lao động là cái bị tác động, không phải yếu tố biến đổi nhanh nhất.","Nguyên liệu là một dạng đối tượng lao động, không phải yếu tố động nhất."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-I.5","p":1,"t":"Trắc nghiệm"},
{"q":"Trong ba mặt của quan hệ sản xuất, mặt giữ vai trò quyết định là:","o":["Quan hệ tổ chức, quản lý sản xuất","Quan hệ phân phối sản phẩm lao động","Quan hệ trao đổi hoạt động cho nhau","Quan hệ sở hữu về tư liệu sản xuất"],"a":[3],"e":"Quan hệ sản xuất gồm ba mặt: sở hữu tư liệu sản xuất, tổ chức – quản lý, phân phối sản phẩm. Quan hệ sở hữu là quan hệ xuất phát, cơ bản, quyết định địa vị của các tập đoàn người trong sản xuất, từ đó quy định hai mặt còn lại.","w":["Quan hệ tổ chức – quản lý có vai trò quan trọng nhưng do quan hệ sở hữu quy định.","Quan hệ phân phối tác động mạnh tới lợi ích nhưng cũng do quan hệ sở hữu quy định.","«Trao đổi hoạt động» không phải một trong ba mặt của quan hệ sản xuất theo giáo trình.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-I.6","p":1,"t":"Trắc nghiệm"},
{"q":"Quy luật cơ bản nhất của sự vận động và phát triển xã hội là quy luật:","o":["Cơ sở hạ tầng quyết định kiến trúc thượng tầng của xã hội","Tồn tại xã hội quyết định ý thức xã hội","Quan hệ sản xuất phù hợp trình độ lực lượng sản xuất","Đấu tranh giai cấp là động lực của mọi xã hội"],"a":[2],"e":"Quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất là quy luật cơ bản nhất của sự vận động, phát triển xã hội: nó chi phối sự vận động của phương thức sản xuất và giải thích sự thay thế các hình thái kinh tế - xã hội.","w":["Quy luật cơ sở hạ tầng quyết định kiến trúc thượng tầng là quy luật quan trọng nhưng phái sinh từ phương thức sản xuất.","Tồn tại xã hội quyết định ý thức xã hội là nguyên lý chung về quan hệ vật chất – tinh thần của xã hội, không phải «quy luật cơ bản nhất».","","Đấu tranh giai cấp chỉ là động lực của xã hội có giai cấp, không phải của «mọi xã hội»."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-I.7","p":1,"t":"Trắc nghiệm"},
{"q":"Khi quan hệ sản xuất không còn phù hợp với trình độ của lực lượng sản xuất thì nó sẽ:","o":["Thúc đẩy lực lượng sản xuất phát triển nhanh hơn","Kìm hãm sự phát triển của lực lượng sản xuất","Tự điều chỉnh mà không cần thay đổi căn bản","Không ảnh hưởng gì đến lực lượng sản xuất"],"a":[1],"e":"Khi quan hệ sản xuất không còn phù hợp (lạc hậu hoặc «vượt trước» quá xa) thì nó trở thành «xiềng xích», kìm hãm lực lượng sản xuất. Mâu thuẫn này đòi hỏi thay quan hệ sản xuất cũ bằng quan hệ sản xuất mới phù hợp hơn.","w":["Chỉ quan hệ sản xuất phù hợp mới thúc đẩy lực lượng sản xuất.","","Mâu thuẫn gay gắt phải được giải quyết bằng cải cách hoặc cách mạng, không tự điều chỉnh.","Quan hệ sản xuất luôn tác động trở lại lực lượng sản xuất, thúc đẩy hoặc kìm hãm."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-I.8","p":1,"t":"Trắc nghiệm"},
{"q":"Cơ sở hạ tầng của xã hội là:","o":["Toàn bộ quan hệ sản xuất hợp thành cơ cấu kinh tế","Hệ thống giao thông, điện, nước và viễn thông của quốc gia","Toàn bộ lực lượng sản xuất của một xã hội","Toàn bộ cơ sở vật chất kỹ thuật của xã hội"],"a":[0],"e":"Giáo trình định nghĩa cơ sở hạ tầng là toàn bộ những quan hệ sản xuất hợp thành cơ cấu kinh tế của một xã hội nhất định (gồm quan hệ sản xuất thống trị, tàn dư và mầm mống). Đây là khái niệm triết học, khác với «hạ tầng kỹ thuật».","w":["","Giao thông, điện, nước là kết cấu hạ tầng kỹ thuật (thuộc tư liệu lao động), không phải cơ sở hạ tầng theo nghĩa triết học.","Lực lượng sản xuất không nằm trong cơ sở hạ tầng; cơ sở hạ tầng là các quan hệ sản xuất.","Cơ sở vật chất kỹ thuật thuộc lực lượng sản xuất, không phải cơ cấu kinh tế."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.3 (Biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng)","c":5,"v":"khớp","id":"dv-I.9","p":1,"t":"Trắc nghiệm"},
{"q":"Trong xã hội có giai cấp, bộ phận có quyền lực mạnh nhất của kiến trúc thượng tầng là:","o":["Đảng phái chính trị","Hệ thống tôn giáo","Nhà nước","Các đoàn thể xã hội"],"a":[2],"e":"Trong xã hội có giai cấp, nhà nước là yếu tố có quyền lực mạnh nhất của kiến trúc thượng tầng và tác động trực tiếp nhất tới cơ sở hạ tầng; nhờ nó giai cấp thống trị chi phối các bộ phận khác (tư tưởng, pháp luật, tổ chức…).","w":["Đảng phái chính trị là bộ phận quan trọng nhưng không có quyền lực cưỡng chế như nhà nước.","Tôn giáo là một hình thái ý thức và thiết chế xã hội, không có quyền lực mạnh nhất.","","Các đoàn thể xã hội không nắm bộ máy quyền lực cưỡng chế."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.3 (Biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng)","c":5,"v":"khớp","id":"dv-I.10","p":1,"t":"Trắc nghiệm"},
{"q":"Quan hệ giữa cơ sở hạ tầng và kiến trúc thượng tầng được hiểu đúng là:","o":["Kiến trúc thượng tầng quyết định cơ sở hạ tầng","Cơ sở hạ tầng quyết định, kiến trúc thượng tầng tác động trở lại","Cơ sở hạ tầng quyết định tuyệt đối, kiến trúc thượng tầng thụ động","Hai bên tồn tại song song, không quyết định lẫn nhau"],"a":[1],"e":"Cơ sở hạ tầng quyết định kiến trúc thượng tầng (cơ sở hạ tầng nào thì kiến trúc thượng tầng ấy; hạ tầng đổi thì sớm muộn thượng tầng đổi). Kiến trúc thượng tầng có tính độc lập tương đối và tác động trở lại, có thể thúc đẩy hoặc kìm hãm.","w":["Đảo ngược quan hệ, rơi vào quan điểm duy tâm về xã hội.","","Tuyệt đối hóa vai trò quyết định, phủ nhận tác động trở lại của kiến trúc thượng tầng.","Hai mặt gắn bó biện chứng, không tồn tại song song tách rời."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.3 (Biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng)","c":5,"v":"khớp","id":"dv-I.11","p":1,"t":"Trắc nghiệm"},
{"q":"\"Tôi coi sự phát triển của những hình thái kinh tế - xã hội là một quá trình lịch sử - tự nhiên.\" Câu nói này của ai?","o":["G.W.F. Hegel","Ph. Ăngghen","V.I. Lênin","C. Mác"],"a":[3],"e":"Câu nói của C. Mác trong Lời tựa lần thứ nhất bộ «Tư bản» (1867). Ý nghĩa: các hình thái kinh tế - xã hội vận động, thay thế nhau theo các quy luật khách quan, không theo ý muốn chủ quan.","w":["Hêghen là nhà duy tâm khách quan, không có học thuyết hình thái kinh tế - xã hội.","Ăngghen cùng sáng lập chủ nghĩa duy vật lịch sử, nhưng câu này là của Mác.","Lênin phát triển và bảo vệ học thuyết, nhưng không phải tác giả câu này.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.4 (Sự phát triển các hình thái kinh tế - xã hội là quá trình lịch sử - tự nhiên); C. Mác, «Tư bản», Lời tựa lần thứ nhất (1867)","c":5,"v":"khớp","id":"dv-I.12","p":1,"t":"Trắc nghiệm"},
{"q":"Cơ sở hạ tầng, theo nghĩa triết học, là hệ thống giao thông, điện, nước của một quốc gia.","o":["Đúng","Sai"],"a":[1],"e":"Sai. Cơ sở hạ tầng (nghĩa triết học) là toàn bộ quan hệ sản xuất hợp thành cơ cấu kinh tế của xã hội. Giao thông, điện, nước là kết cấu hạ tầng kỹ thuật, thuộc tư liệu lao động của lực lượng sản xuất.","w":["Nhầm thuật ngữ triết học với nghĩa đời thường của «hạ tầng».",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.3 (Biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng)","c":5,"v":"khớp","id":"dv-I.13","p":1,"t":"Đúng/Sai","f":1},
{"q":"Kiến trúc thượng tầng có thể thúc đẩy hoặc kìm hãm sự phát triển của cơ sở hạ tầng.","o":["Đúng","Sai"],"a":[0],"e":"Đúng. Kiến trúc thượng tầng do cơ sở hạ tầng quyết định nhưng có tính độc lập tương đối và tác động trở lại: thúc đẩy khi phù hợp với quy luật kinh tế khách quan, kìm hãm khi đi ngược.","w":["","Phủ nhận vai trò tác động trở lại là rơi vào quan điểm kinh tế tầm thường, máy móc."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.3 (Biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng)","c":5,"v":"khớp","id":"dv-I.14","p":1,"t":"Đúng/Sai","f":1},
{"q":"Con người có thể tùy ý chọn quan hệ sản xuất mà không cần căn cứ vào trình độ lực lượng sản xuất.","o":["Đúng","Sai"],"a":[1],"e":"Sai. Quan hệ sản xuất do trình độ lực lượng sản xuất quyết định; con người không thể tùy ý lựa chọn. Áp đặt quan hệ sản xuất «vượt trước» trình độ lực lượng sản xuất là vi phạm quy luật, biểu hiện bệnh chủ quan duy ý chí.","w":["Bỏ qua tính khách quan của quy luật quan hệ sản xuất phù hợp với trình độ lực lượng sản xuất.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-I.15","p":1,"t":"Đúng/Sai","f":1},
{"q":"Sắp xếp các hình thái kinh tế - xã hội có trong lịch sử theo trình tự từ thấp đến cao:\n(1) Chiếm hữu nô lệ · (2) Cộng sản nguyên thủy · (3) Tư bản chủ nghĩa · (4) Phong kiến","o":["2 → 1 → 4 → 3","1 → 2 → 4 → 3","2 → 4 → 1 → 3","2 → 1 → 3 → 4"],"a":[0],"e":"Thứ tự: Cộng sản nguyên thủy → Chiếm hữu nô lệ → Phong kiến → Tư bản chủ nghĩa (rồi hướng tới cộng sản chủ nghĩa). Đây là năm hình thái giáo trình nêu; xã hội có giai cấp và nhà nước bắt đầu từ chiếm hữu nô lệ.","w":["","Chiếm hữu nô lệ không thể có trước cộng sản nguyên thủy — hình thái đầu tiên chưa có giai cấp.","Phong kiến ra đời sau chiếm hữu nô lệ, không phải trước.","Tư bản chủ nghĩa ra đời từ lòng xã hội phong kiến, nên phong kiến phải đứng trước."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.4 (Sự phát triển các hình thái kinh tế - xã hội là quá trình lịch sử - tự nhiên)","c":5,"v":"khớp","id":"dv-I.16","p":1,"t":"Sắp xếp"},
{"q":"Sắp xếp các bước vận động của quy luật quan hệ sản xuất phù hợp với trình độ lực lượng sản xuất:\n(1) Quan hệ sản xuất cũ trở nên không còn phù hợp\n(2) Lực lượng sản xuất phát triển lên trình độ mới\n(3) Quan hệ sản xuất mới phù hợp được xác lập\n(4) Mâu thuẫn gay gắt, đòi hỏi phải thay đổi","o":["2 → 1 → 4 → 3","1 → 2 → 4 → 3","2 → 4 → 1 → 3","4 → 2 → 1 → 3"],"a":[0],"e":"Lực lượng sản xuất là yếu tố động, luôn biến đổi trước (2) → quan hệ sản xuất cũ dần không phù hợp (1) → mâu thuẫn trở nên gay gắt (4) → được giải quyết bằng việc xác lập quan hệ sản xuất mới phù hợp (3). Sự phù hợp mới lại bị phá vỡ: đó là «cân bằng động».","w":["","Quan hệ sản xuất không tự lạc hậu trước; nó chỉ trở nên không phù hợp khi lực lượng sản xuất đã phát triển lên.","Mâu thuẫn chỉ gay gắt sau khi quan hệ sản xuất cũ đã trở nên không phù hợp.","Mâu thuẫn không thể xuất hiện trước khi lực lượng sản xuất phát triển."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-I.17","p":1,"t":"Sắp xếp"},
{"q":"Một xưởng may đầu tư dây chuyền tự động hiện đại nhưng vẫn quản lý theo lối gia đình, chia lương cào bằng. Theo quy luật quan hệ sản xuất phù hợp với lực lượng sản xuất, hệ quả dễ xảy ra là:","o":["Năng suất chắc chắn tăng mạnh nhờ máy móc hiện đại","Cách quản lý cũ kìm hãm hiệu quả dây chuyền mới","Công nhân tự động nâng cao tay nghề theo máy móc","Quan hệ sản xuất tự động thay đổi theo máy móc mới"],"a":[1],"e":"Dây chuyền tự động là lực lượng sản xuất mới; quản lý kiểu gia đình, chia lương cào bằng là quan hệ tổ chức – quản lý và phân phối lạc hậu. Quan hệ sản xuất không phù hợp sẽ kìm hãm hiệu quả của lực lượng sản xuất.","w":["Máy móc chỉ phát huy khi quan hệ sản xuất phù hợp; «chắc chắn tăng mạnh» là bỏ qua tác động trở lại của quan hệ sản xuất.","","Tay nghề không «tự động» nâng lên; cần đào tạo và cơ chế phù hợp.","Quan hệ sản xuất không tự thay đổi ngay; phải có sự điều chỉnh chủ động của con người."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-I.18","p":1,"t":"Trắc nghiệm"},
{"q":"Trong nền kinh tế số, dữ liệu và trí tuệ nhân tạo tham gia trực tiếp vào quá trình sản xuất. Điều này minh họa rõ nhất luận điểm:","o":["Khoa học trở thành lực lượng sản xuất trực tiếp","Kiến trúc thượng tầng quyết định cơ sở hạ tầng","Ý thức xã hội quyết định tồn tại xã hội","Quan hệ sản xuất luôn quyết định lực lượng sản xuất"],"a":[0],"e":"Giáo trình nêu: trong cách mạng khoa học và công nghệ hiện đại, «tri thức khoa học ngày càng trở thành lực lượng sản xuất trực tiếp» — khoa học thâm nhập vào mọi yếu tố của sản xuất, trở thành mắt khâu bên trong của quá trình sản xuất. Dữ liệu, AI là ví dụ điển hình.","w":["","Ngược quan hệ: cơ sở hạ tầng mới quyết định kiến trúc thượng tầng.","Ngược quan hệ: tồn tại xã hội quyết định ý thức xã hội.","Lực lượng sản xuất mới quyết định quan hệ sản xuất; «luôn» là tuyệt đối hóa sai."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất); Ch.1, mục II (cách mạng khoa học và công nghệ hiện đại)","c":5,"v":"khớp","id":"dv-I.19","p":1,"t":"Trắc nghiệm"},
{"q":"Trước Đổi mới, việc xây dựng quan hệ sản xuất vượt quá trình độ lực lượng sản xuất là vi phạm quy luật khách quan. Văn kiện Đại hội VI (1986) gọi đó là biểu hiện của bệnh:","o":["Chủ quan duy ý chí","Thực dụng chủ nghĩa","Cơ hội chủ nghĩa","Hình thức chủ nghĩa"],"a":[0],"e":"Văn kiện Đại hội VI (1986) thẳng thắn chỉ ra «bệnh chủ quan duy ý chí», lối suy nghĩ và hành động giản đơn, nóng vội, chạy theo nguyện vọng chủ quan — biểu hiện rõ nhất là xây dựng quan hệ sản xuất vượt quá trình độ lực lượng sản xuất.","w":["","Thực dụng chủ nghĩa là chỉ chạy theo lợi ích trước mắt, không phải tên gọi Đại hội VI dùng.","Cơ hội chủ nghĩa là lợi dụng thời cơ vì lợi ích riêng, không đúng với bản chất sai lầm này.","Hình thức chủ nghĩa là chạy theo bề ngoài, không phải chẩn đoán của Đại hội VI."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất); Văn kiện Đại hội đại biểu toàn quốc lần thứ VI (1986)","c":5,"v":"khớp","id":"dv-I.20","p":1,"t":"Trắc nghiệm"},
{"q":"Ghép mỗi yếu tố với vai trò của nó:\n1. Người lao động · 2. Công cụ lao động · 3. Quan hệ sở hữu\na. Yếu tố động nhất của lực lượng sản xuất\nb. Yếu tố quyết định của lực lượng sản xuất\nc. Mặt quyết định của quan hệ sản xuất","o":["1-a, 2-b, 3-c","1-b, 2-a, 3-c","1-c, 2-a, 3-b","1-b, 2-c, 3-a"],"a":[1],"e":"Người lao động → yếu tố quyết định của lực lượng sản xuất (1-b). Công cụ lao động → yếu tố động nhất (2-a). Quan hệ sở hữu → mặt quyết định của quan hệ sản xuất (3-c).","w":["Đảo vai trò người lao động và công cụ lao động — đúng cái bẫy «quyết định» với «động nhất».","","Người lao động không phải một mặt của quan hệ sản xuất; quan hệ sở hữu không phải yếu tố quyết định của lực lượng sản xuất.","Công cụ lao động thuộc lực lượng sản xuất, không phải «mặt quyết định của quan hệ sản xuất»."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-I.21","p":1,"t":"Ghép đôi"},
{"q":"Việt Nam đi lên chủ nghĩa xã hội \"bỏ qua chế độ tư bản chủ nghĩa\". Theo Đảng ta, \"bỏ qua\" được hiểu là bỏ qua:","o":["Sự thống trị của quan hệ sản xuất tư bản chủ nghĩa","Mọi thành tựu khoa học và công nghệ của chủ nghĩa tư bản","Toàn bộ giai đoạn phát triển lực lượng sản xuất hiện đại","Quy luật quan hệ sản xuất phù hợp với lực lượng sản xuất"],"a":[0],"e":"Đảng ta (từ Đại hội IX) xác định quá độ lên chủ nghĩa xã hội bỏ qua chế độ tư bản chủ nghĩa là bỏ qua việc xác lập vị trí thống trị của quan hệ sản xuất và kiến trúc thượng tầng tư bản chủ nghĩa, đồng thời tiếp thu, kế thừa những thành tựu nhân loại đạt được dưới chủ nghĩa tư bản, nhất là khoa học và công nghệ.","w":["","Ngược lại: phải tiếp thu thành tựu khoa học, công nghệ của chủ nghĩa tư bản.","Không thể bỏ qua sự phát triển lực lượng sản xuất; phải công nghiệp hóa, hiện đại hóa.","Không thể bỏ qua quy luật khách quan; quy luật này vẫn chi phối mọi xã hội."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.4 (Sự phát triển các hình thái kinh tế - xã hội là quá trình lịch sử - tự nhiên); Văn kiện Đại hội IX (2001)","c":5,"v":"khớp","id":"dv-I.22","p":1,"t":"Trắc nghiệm"},
{"q":"Một bạn nói: \"Chỉ cần ban hành nghị quyết xây dựng nền kinh tế hiện đại là lực lượng sản xuất sẽ lập tức hiện đại theo.\" Lập luận này sai chủ yếu ở chỗ:","o":["Coi ý chí chủ quan quyết định lực lượng sản xuất","Đề cao vai trò của khoa học và công nghệ hiện đại","Thừa nhận nhà nước có vai trò quản lý nền kinh tế","Cho rằng kiến trúc thượng tầng có tác động trở lại"],"a":[0],"e":"Nghị quyết thuộc kiến trúc thượng tầng, có tác động trở lại nhưng không thể thay thế quá trình phát triển khách quan của lực lượng sản xuất (cần thời gian, vốn, con người, công nghệ). Tin rằng ra nghị quyết là lực lượng sản xuất «lập tức» hiện đại là coi ý chí quyết định — chủ quan duy ý chí.","w":["","Đề cao khoa học công nghệ là đúng, không phải chỗ sai của lập luận.","Nhà nước có vai trò quản lý kinh tế là đúng.","Kiến trúc thượng tầng có tác động trở lại là đúng; cái sai là tuyệt đối hóa tác động đó."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất), Ch.3, mục I.3 (Biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng)","c":5,"v":"khớp","id":"dv-I.23","p":1,"t":"Tìm lỗi lập luận"},
{"q":"\"Xã hội nào cũng phải đi lần lượt đủ năm hình thái, không thể có ngoại lệ.\" Nhận định này:","o":["Tuyệt đối hóa tính quy luật, bỏ qua tính đặc thù lịch sử","Hoàn toàn đúng với học thuyết hình thái kinh tế - xã hội","Đúng, vì lịch sử là quá trình lịch sử - tự nhiên","Sai, vì lịch sử hoàn toàn ngẫu nhiên, không có quy luật"],"a":[0],"e":"Giáo trình: tiến trình lịch sử vừa tuân theo quy luật chung vừa có tính đặc thù. Trong điều kiện nhất định, một dân tộc có thể bỏ qua một hoặc vài hình thái (như Việt Nam quá độ lên chủ nghĩa xã hội bỏ qua chế độ tư bản chủ nghĩa). Đòi mọi xã hội đi đủ năm hình thái là tuyệt đối hóa tính quy luật.","w":["","Học thuyết thừa nhận khả năng «bỏ qua», nên nhận định này không đúng với học thuyết.","«Lịch sử - tự nhiên» là theo quy luật khách quan, nhưng không có nghĩa mọi dân tộc phải đi đủ các hình thái.","Phủ nhận quy luật lịch sử cũng sai; lịch sử có quy luật."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.4 (Sự phát triển các hình thái kinh tế - xã hội là quá trình lịch sử - tự nhiên)","c":5,"v":"khớp","id":"dv-I.24","p":1,"t":"Tìm lỗi lập luận"},
{"q":"\"Cứ mua thật nhiều máy móc hiện đại là năng suất sẽ tăng, không cần đào tạo người lao động.\" Sai lầm của ý kiến này là:","o":["Bỏ qua vai trò quyết định của người lao động","Đề cao quá mức vai trò của quan hệ phân phối","Phủ nhận vai trò của công cụ lao động","Cho rằng khoa học là lực lượng sản xuất"],"a":[0],"e":"Người lao động là yếu tố quyết định của lực lượng sản xuất; máy móc chỉ phát huy khi người lao động đủ trình độ sử dụng. Ý kiến trên chỉ thấy công cụ, bỏ qua con người — cách nhìn phiến diện.","w":["","Ý kiến không đề cập quan hệ phân phối.","Ngược lại, ý kiến đề cao công cụ lao động.","Ý kiến không bàn về khoa học là lực lượng sản xuất."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-I.25","p":1,"t":"Tìm lỗi lập luận"},
{"q":"\"Cơ sở hạ tầng quyết định kiến trúc thượng tầng, vậy pháp luật và chính sách chẳng có vai trò gì.\" Lập luận này mắc lỗi:","o":["Tuyệt đối hóa vai trò quyết định, phủ nhận tác động trở lại","Đánh giá đúng mối quan hệ giữa cơ sở hạ tầng và kiến trúc thượng tầng","Coi kiến trúc thượng tầng quyết định cơ sở hạ tầng","Đồng nhất cơ sở hạ tầng với hạ tầng kỹ thuật"],"a":[0],"e":"Cơ sở hạ tầng quyết định, nhưng kiến trúc thượng tầng (nhất là nhà nước, pháp luật, chính sách) có tính độc lập tương đối và tác động trở lại mạnh mẽ. Phủ nhận vai trò đó là tuyệt đối hóa vai trò quyết định — quan điểm duy vật kinh tế tầm thường.","w":["","Lập luận đánh giá sai, vì phủ nhận tác động trở lại.","Lập luận không coi thượng tầng quyết định hạ tầng; nó mắc lỗi ngược lại.","Lập luận không nhầm cơ sở hạ tầng với hạ tầng kỹ thuật."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.3 (Biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng)","c":5,"v":"khớp","id":"dv-I.26","p":1,"t":"Tìm lỗi lập luận"},
{"q":"Các nền tảng gọi xe, giao đồ ăn kết nối hàng triệu tài xế làm việc linh hoạt, không theo hợp đồng lao động truyền thống. Dưới góc độ triết học, đây chủ yếu là sự biến đổi của:","o":["Quan hệ tổ chức và quản lý sản xuất","Ý thức thẩm mỹ của người tiêu dùng","Điều kiện tự nhiên và hoàn cảnh địa lý","Hình thức chính thể của nhà nước"],"a":[0],"e":"Kinh tế nền tảng (gọi xe, giao đồ ăn) thay đổi cách tổ chức, quản lý lao động và cách phân phối thu nhập — tức là biến đổi một mặt của quan hệ sản xuất. Sự biến đổi này do lực lượng sản xuất mới (công nghệ số, thuật toán) thúc đẩy.","w":["","Ý thức thẩm mỹ là một hình thái ý thức xã hội, không liên quan trực tiếp tới cách tổ chức lao động.","Điều kiện tự nhiên không thay đổi trong hiện tượng này.","Hình thức chính thể của nhà nước không bị tác động."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-I.27","p":1,"t":"Tình huống thời sự"},
{"q":"AI và robot thay thế nhiều công việc lặp lại, đồng thời đòi hỏi người lao động có kỹ năng mới. Điều này cho thấy:","o":["Người lao động phải nâng trình độ theo công cụ mới","Người lao động không còn vai trò gì trong sản xuất hiện đại","Công cụ lao động không ảnh hưởng tới người lao động","Quan hệ sản xuất quyết định sự ra đời của trí tuệ nhân tạo"],"a":[0],"e":"Các yếu tố của lực lượng sản xuất tác động lẫn nhau: công cụ mới (AI, robot) đòi hỏi người lao động nâng trình độ, kỹ năng; ngược lại người lao động vẫn là yếu tố quyết định, sáng tạo và sử dụng công cụ.","w":["","Người lao động vẫn là yếu tố quyết định; AI cũng do con người tạo ra và vận hành.","Công cụ lao động tác động mạnh tới người lao động (đòi hỏi kỹ năng mới).","AI là thành tựu của lực lượng sản xuất (khoa học, công nghệ), không do quan hệ sản xuất quyết định ra đời."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-I.28","p":1,"t":"Tình huống thời sự"},
{"q":"Việt Nam xác định chuyển đổi số là động lực tăng trưởng mới. Theo quy luật quan hệ sản xuất phù hợp với lực lượng sản xuất, để chuyển đổi số thành công cần đồng thời:","o":["Đổi mới thể chế, quản lý cho phù hợp công nghệ mới","Chỉ cần nhập khẩu thật nhiều thiết bị công nghệ cao","Giữ nguyên toàn bộ cơ chế quản lý cũ cho ổn định","Chờ lực lượng sản xuất tự phát triển, không can thiệp"],"a":[0],"e":"Lực lượng sản xuất mới (công nghệ số) cần quan hệ sản xuất và thể chế quản lý phù hợp. Chỉ mua thiết bị mà giữ cơ chế cũ thì quan hệ sản xuất sẽ kìm hãm công nghệ — nên phải đồng thời đổi mới thể chế, quản lý.","w":["","Chỉ chú ý lực lượng sản xuất, bỏ qua yêu cầu quan hệ sản xuất phải phù hợp.","Cơ chế cũ không phù hợp sẽ kìm hãm lực lượng sản xuất mới.","Quan hệ sản xuất tác động trở lại; thụ động chờ đợi là bỏ qua vai trò chủ động của con người."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-I.29","p":1,"t":"Tình huống thời sự"},
{"q":"Nhiều địa phương chuyển từ sản xuất nông nghiệp manh mún sang liên kết chuỗi, hợp tác xã kiểu mới để áp dụng công nghệ cao. Đây là ví dụ về:","o":["Điều chỉnh quan hệ sản xuất cho phù hợp","Kiến trúc thượng tầng quyết định cơ sở hạ tầng","Ý thức xã hội vượt trước tồn tại xã hội","Xóa bỏ hoàn toàn vai trò của người nông dân"],"a":[0],"e":"Khi lực lượng sản xuất (công nghệ cao) phát triển, lối sản xuất manh mún không còn phù hợp. Liên kết chuỗi, hợp tác xã kiểu mới là điều chỉnh quan hệ tổ chức – quản lý và phân phối cho phù hợp với trình độ lực lượng sản xuất.","w":["","Đây là thay đổi trong quan hệ sản xuất (cơ sở hạ tầng), không phải thượng tầng quyết định hạ tầng.","Không liên quan tới ý thức xã hội vượt trước.","Người nông dân vẫn là người lao động trong chuỗi liên kết."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-I.30","p":1,"t":"Tình huống thời sự"},
{"q":"Định nghĩa kinh điển về giai cấp của V.I. Lênin được trình bày trong tác phẩm nào?","o":["Nhà nước và cách mạng","Sáng kiến vĩ đại","Bút ký triết học","Làm gì?"],"a":[1],"e":"Giáo trình viết: trong tác phẩm «Sáng kiến vĩ đại» (1919), lần đầu tiên V.I. Lênin đưa ra định nghĩa hoàn chỉnh về giai cấp, chỉ ra những đặc trưng cơ bản, phổ biến và ổn định nhất để phân biệt các giai cấp.","w":["«Nhà nước và cách mạng» (1917) bàn về nguồn gốc, bản chất nhà nước và chuyên chính vô sản.","","«Bút ký triết học» là ghi chép nghiên cứu phép biện chứng, Hêghen…","«Làm gì?» (1902) bàn về xây dựng đảng kiểu mới."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.1 (Vấn đề giai cấp và đấu tranh giai cấp); Ch.1, mục II (giai đoạn Lênin)","c":5,"v":"khớp","id":"dv-II.1","p":2,"t":"Trắc nghiệm"},
{"q":"Theo định nghĩa của Lênin, đặc trưng giữ vai trò chi phối các đặc trưng còn lại của giai cấp là sự khác nhau về:","o":["Trình độ học vấn và nghề nghiệp","Vai trò trong tổ chức lao động xã hội","Quan hệ đối với tư liệu sản xuất","Cách thức và quy mô thu nhập"],"a":[2],"e":"Định nghĩa của Lênin nêu bốn đặc trưng: khác nhau về địa vị trong hệ thống sản xuất, về quan hệ đối với tư liệu sản xuất, về vai trò trong tổ chức lao động, về cách thức và quy mô hưởng thụ của cải. Trong đó quan hệ đối với tư liệu sản xuất (sở hữu) là đặc trưng chủ yếu, quy định các đặc trưng còn lại.","w":["Học vấn, nghề nghiệp không nằm trong định nghĩa giai cấp của Lênin.","Vai trò trong tổ chức lao động là một đặc trưng, nhưng do quan hệ sở hữu quy định.","","Cách thức, quy mô thu nhập là một đặc trưng, nhưng cũng do quan hệ sở hữu quy định."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.1 (Vấn đề giai cấp và đấu tranh giai cấp)","c":5,"v":"khớp","id":"dv-II.2","p":2,"t":"Trắc nghiệm"},
{"q":"Nguyên nhân trực tiếp dẫn đến sự ra đời của giai cấp là:","o":["Chế độ tư hữu về tư liệu sản xuất","Sự xuất hiện của sản phẩm dư thừa","Sự khác biệt về sức khỏe, tài năng","Chiến tranh giữa các bộ lạc"],"a":[0],"e":"Nguyên nhân sâu xa: lực lượng sản xuất phát triển tạo ra «của dư» tương đối. Nguyên nhân trực tiếp: chế độ tư hữu về tư liệu sản xuất xuất hiện, làm xã hội phân hóa thành người chiếm hữu và người bị chiếm đoạt.","w":["","Sản phẩm dư thừa (do lực lượng sản xuất phát triển) là nguyên nhân sâu xa, không phải trực tiếp.","Khác biệt sức khỏe, tài năng là yếu tố tự nhiên, không sinh ra giai cấp.","Chiến tranh có thể đẩy nhanh sự phân hóa (tù binh thành nô lệ) nhưng không phải nguyên nhân trực tiếp."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.1 (Vấn đề giai cấp và đấu tranh giai cấp)","c":5,"v":"khớp","id":"dv-II.3","p":2,"t":"Trắc nghiệm"},
{"q":"Trong xã hội có giai cấp, động lực trực tiếp và quan trọng của lịch sử là:","o":["Sự phát triển của khoa học","Hoạt động của các vĩ nhân","Sự gia tăng dân số","Đấu tranh giai cấp"],"a":[3],"e":"Giáo trình: «Đấu tranh giai cấp là động lực phát triển của xã hội, nhưng không phải là động lực duy nhất mà là một động lực trực tiếp và quan trọng» trong xã hội có giai cấp; đỉnh cao của nó là cách mạng xã hội. (Đề cũ hay hỏi: «một trong những động lực phát triển của xã hội có giai cấp».)","w":["Khoa học thúc đẩy lực lượng sản xuất, nhưng không phải động lực trực tiếp của lịch sử xã hội có giai cấp.","Coi vĩ nhân là động lực lịch sử là quan điểm duy tâm.","Dân số chỉ là điều kiện của tồn tại xã hội.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.1 (Vấn đề giai cấp và đấu tranh giai cấp)","c":5,"v":"khớp","id":"dv-II.4","p":2,"t":"Trắc nghiệm"},
{"q":"Giai cấp cơ bản trong một xã hội là giai cấp:","o":["Chiếm số đông nhất trong dân cư","Gắn với phương thức sản xuất thống trị","Có trình độ học vấn cao nhất xã hội","Tồn tại qua nhiều hình thái lịch sử nhất"],"a":[1],"e":"Giáo trình: «Giai cấp cơ bản là giai cấp gắn với phương thức sản xuất thống trị» — chủ nô và nô lệ, địa chủ và nông dân, tư sản và vô sản. Giai cấp không cơ bản gắn với phương thức sản xuất tàn dư hoặc mầm mống.","w":["Số đông chưa chắc là giai cấp cơ bản (VD: nông dân trong xã hội tư bản).","","Học vấn không phải tiêu chí xác định giai cấp.","Tồn tại lâu qua nhiều hình thái không phải tiêu chí; tiêu chí là gắn với phương thức sản xuất thống trị."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.1 (Vấn đề giai cấp và đấu tranh giai cấp)","c":5,"v":"khớp","id":"dv-II.5","p":2,"t":"Trắc nghiệm"},
{"q":"Các hình thức cộng đồng người xuất hiện trước dân tộc, theo trình tự lịch sử, là:","o":["Bộ tộc, bộ lạc, thị tộc","Bộ lạc, thị tộc, bộ tộc","Thị tộc, bộ lạc, bộ tộc","Thị tộc, bộ tộc, bộ lạc"],"a":[2],"e":"Trình tự các hình thức cộng đồng người: thị tộc (cùng huyết thống) → bộ lạc (liên minh các thị tộc) → bộ tộc (hình thành khi phân chia giai cấp, trên một lãnh thổ) → dân tộc (hình thức cao nhất).","w":["Đảo ngược toàn bộ trình tự.","Thị tộc là hình thức đầu tiên, phải đứng trước bộ lạc.","","Bộ lạc có trước bộ tộc."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.2 (Dân tộc)","c":5,"v":"khớp","id":"dv-II.6","p":2,"t":"Trắc nghiệm"},
{"q":"Đặc trưng được coi là quan trọng nhất của dân tộc, gắn kết các bộ phận dân cư thành một cộng đồng thống nhất, bền vững là:","o":["Chung ngôn ngữ làm công cụ giao tiếp","Chung một lãnh thổ ổn định","Chung nền văn hóa và tâm lý dân tộc","Chung phương thức sinh hoạt kinh tế"],"a":[3],"e":"Giáo trình Triết học phân tích: «tác nhân cơ bản dẫn tới việc chuyển từ hình thức cộng đồng trước dân tộc sang dân tộc là tác nhân kinh tế»; mối liên hệ kinh tế (nhất là thị trường) làm tăng tính thống nhất, ổn định, bền vững của cộng đồng. Giáo trình Chủ nghĩa xã hội khoa học nói thẳng: chung phương thức sinh hoạt kinh tế là đặc trưng quan trọng nhất của dân tộc.","w":["Ngôn ngữ chung là đặc trưng cơ bản, nhưng không phải quan trọng nhất.","Bẫy: giáo trình Triết học gọi lãnh thổ là «đặc trưng quan trọng không thể thiếu được» — quan trọng nhưng không phải «quan trọng nhất».","Văn hóa, tâm lý là đặc trưng bền vững, nhưng hình thành trên cơ sở kinh tế.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.2 (Dân tộc); GT Chủ nghĩa xã hội khoa học (Bộ GD&ĐT, 2021), Ch.6","c":5,"v":"dễ nhầm","id":"dv-II.7","p":2,"t":"Trắc nghiệm","k":"Đã sửa đề: bản gốc ghi «Theo giáo trình…», nhưng giáo trình Triết học không dùng chữ «quan trọng nhất» cho kinh tế (chỉ nói kinh tế là tác nhân cơ bản), còn gọi lãnh thổ là «đặc trưng quan trọng không thể thiếu». Cụm «quan trọng nhất» nằm ở giáo trình CNXH khoa học."},
{"q":"Đặc điểm nổi bật của quá trình hình thành dân tộc Việt Nam là:","o":["Hình thành sớm, gắn với dựng nước và giữ nước","Hình thành cùng sự ra đời của chủ nghĩa tư bản","Hình thành sau Cách mạng Tháng Tám năm 1945","Hình thành do sự hợp nhất các thuộc địa Pháp"],"a":[0],"e":"Giáo trình: «Dân tộc Việt Nam được hình thành rất sớm trong lịch sử gắn liền với nhu cầu dựng nước và giữ nước, với quá trình đấu tranh chống ngoại xâm và cải tạo thiên nhiên» (trị thủy). Khác con đường phương Tây, nơi dân tộc hình thành cùng chủ nghĩa tư bản.","w":["","Đây là con đường điển hình ở châu Âu, không phải Việt Nam.","Dân tộc Việt Nam đã hình thành từ hàng nghìn năm trước, trước 1945 rất lâu.","Sai lịch sử; dân tộc Việt Nam có trước thời Pháp thuộc."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.2 (Dân tộc)","c":5,"v":"khớp","id":"dv-II.8","p":2,"t":"Trắc nghiệm"},
{"q":"\"Hãy xóa bỏ tình trạng người bóc lột người thì tình trạng dân tộc này bóc lột dân tộc khác cũng sẽ bị xóa bỏ.\" Luận điểm này thể hiện:","o":["Vấn đề dân tộc quyết định vấn đề giai cấp","Vấn đề dân tộc và giai cấp tách rời nhau","Vấn đề giai cấp quyết định vấn đề dân tộc","Vấn đề dân tộc có trước vấn đề giai cấp"],"a":[2],"e":"Luận điểm trong «Tuyên ngôn của Đảng Cộng sản» (1848): áp bức giai cấp là nguồn gốc sâu xa của áp bức dân tộc, nên vấn đề giai cấp quyết định khuynh hướng và cách giải quyết vấn đề dân tộc.","w":["Đảo ngược: giai cấp mới là yếu tố quyết định.","Hai vấn đề gắn bó chặt chẽ, không tách rời.","","Luận điểm không bàn chuyện cái nào có trước, mà bàn cái nào quyết định."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.3 (Mối quan hệ giai cấp - dân tộc - nhân loại)","c":5,"v":"khớp","id":"dv-II.9","p":2,"t":"Trắc nghiệm"},
{"q":"Ở Việt Nam, mối quan hệ giai cấp và dân tộc được thể hiện tập trung trong đường lối:","o":["Ưu tiên dân tộc, tạm gác vấn đề giai cấp","Độc lập dân tộc gắn liền với chủ nghĩa xã hội","Đấu tranh giai cấp là nhiệm vụ trung tâm","Hội nhập quốc tế là điều kiện tiên quyết nhất"],"a":[1],"e":"Ở Việt Nam, quan hệ giai cấp – dân tộc thể hiện tập trung ở đường lối độc lập dân tộc gắn liền với chủ nghĩa xã hội: độc lập dân tộc là điều kiện tiên quyết để xây dựng chủ nghĩa xã hội, chủ nghĩa xã hội là cơ sở bảo đảm vững chắc cho độc lập dân tộc.","w":["Tách rời hai vấn đề, trái với đường lối kết hợp của Đảng.","","Nhiệm vụ trung tâm hiện nay là phát triển kinh tế; «đấu tranh giai cấp là trung tâm» là cách nói sai.","Hội nhập quốc tế là chủ trương quan trọng nhưng không phải nội dung cốt lõi của quan hệ giai cấp – dân tộc."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.3 (Mối quan hệ giai cấp - dân tộc - nhân loại)","c":5,"v":"khớp","id":"dv-II.10","p":2,"t":"Trắc nghiệm"},
{"q":"Giai cấp xuất hiện ngay từ khi xã hội loài người hình thành.","o":["Đúng","Sai"],"a":[1],"e":"Sai. Xã hội cộng sản nguyên thủy chưa có giai cấp. Giai cấp chỉ xuất hiện khi lực lượng sản xuất phát triển tạo ra của dư và chế độ tư hữu ra đời (bắt đầu từ chiếm hữu nô lệ); giai cấp gắn với những giai đoạn lịch sử nhất định của sản xuất.","w":["Bỏ qua tính lịch sử của giai cấp.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.1 (Vấn đề giai cấp và đấu tranh giai cấp)","c":5,"v":"khớp","id":"dv-II.11","p":2,"t":"Đúng/Sai","f":1},
{"q":"Đấu tranh giai cấp chỉ diễn ra dưới hình thức bạo lực vũ trang.","o":["Đúng","Sai"],"a":[1],"e":"Sai. Đấu tranh giai cấp có nhiều hình thức: kinh tế, chính trị, tư tưởng; đỉnh cao là đấu tranh chính trị và cách mạng xã hội. Bạo lực vũ trang chỉ là một hình thức trong những điều kiện nhất định.","w":["Từ «chỉ» tuyệt đối hóa một hình thức — dấu hiệu thường gặp của nhận định sai.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.1 (Vấn đề giai cấp và đấu tranh giai cấp)","c":5,"v":"khớp","id":"dv-II.12","p":2,"t":"Đúng/Sai","f":1},
{"q":"Ở Việt Nam, dân tộc hình thành sớm, trước khi chủ nghĩa tư bản xuất hiện.","o":["Đúng","Sai"],"a":[0],"e":"Đúng. Giáo trình: ở Trung Quốc, Ấn Độ, Việt Nam… dân tộc hình thành rất sớm, không gắn với sự ra đời của chủ nghĩa tư bản; ở Việt Nam do yêu cầu dựng nước, giữ nước, chống ngoại xâm và trị thủy.","w":["","Áp dụng máy móc con đường hình thành dân tộc ở châu Âu."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.2 (Dân tộc)","c":5,"v":"khớp","id":"dv-II.13","p":2,"t":"Đúng/Sai","f":1},
{"q":"Trong xã hội có giai cấp, lợi ích giai cấp có thể chi phối cả quan hệ giữa các dân tộc.","o":["Đúng","Sai"],"a":[0],"e":"Đúng. Vấn đề giai cấp quyết định khuynh hướng giải quyết vấn đề dân tộc; áp bức giai cấp là nguồn gốc sâu xa của áp bức dân tộc. Lợi ích của giai cấp cầm quyền chi phối chính sách đối với các dân tộc khác.","w":["","Phủ nhận mối quan hệ giai cấp – dân tộc."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.3 (Mối quan hệ giai cấp - dân tộc - nhân loại)","c":5,"v":"khớp","id":"dv-II.14","p":2,"t":"Đúng/Sai","f":1},
{"q":"Sắp xếp quá trình ra đời của giai cấp theo đúng trình tự:\n(1) Xuất hiện sản phẩm dư thừa · (2) Lực lượng sản xuất phát triển · (3) Xã hội phân chia thành giai cấp · (4) Chế độ tư hữu ra đời","o":["2 → 1 → 4 → 3","1 → 2 → 4 → 3","2 → 4 → 1 → 3","4 → 2 → 1 → 3"],"a":[0],"e":"Lực lượng sản xuất phát triển (2) → có sản phẩm dư thừa (1) — nguyên nhân sâu xa → chế độ tư hữu ra đời (4) — nguyên nhân trực tiếp → xã hội phân chia thành giai cấp (3).","w":["","Của dư là kết quả của lực lượng sản xuất phát triển, không thể có trước.","Tư hữu chỉ xuất hiện khi đã có của dư để chiếm hữu.","Tư hữu không thể có trước khi lực lượng sản xuất tạo ra của dư."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.1 (Vấn đề giai cấp và đấu tranh giai cấp)","c":5,"v":"khớp","id":"dv-II.15","p":2,"t":"Sắp xếp"},
{"q":"Ghép giai cấp cơ bản với xã hội tương ứng:\n1. Chiếm hữu nô lệ · 2. Phong kiến · 3. Tư bản chủ nghĩa\na. Địa chủ và nông dân\nb. Tư sản và vô sản\nc. Chủ nô và nô lệ","o":["1-c, 2-a, 3-b","1-a, 2-c, 3-b","1-c, 2-b, 3-a","1-b, 2-a, 3-c"],"a":[0],"e":"Giáo trình liệt kê đúng ba cặp giai cấp cơ bản: chủ nô – nô lệ (chiếm hữu nô lệ), địa chủ – nông dân (phong kiến), tư sản – vô sản (tư bản chủ nghĩa).","w":["","Đặt địa chủ – nông dân vào chiếm hữu nô lệ và chủ nô – nô lệ vào phong kiến là sai.","Tư sản – vô sản thuộc tư bản chủ nghĩa, không phải phong kiến.","Tư sản – vô sản không phải giai cấp cơ bản của chiếm hữu nô lệ."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.1 (Vấn đề giai cấp và đấu tranh giai cấp)","c":5,"v":"khớp","id":"dv-II.16","p":2,"t":"Ghép đôi"},
{"q":"Theo Đảng Cộng sản Việt Nam, nội dung chủ yếu của đấu tranh giai cấp trong giai đoạn hiện nay là:","o":["Thực hiện thắng lợi công nghiệp hóa, hiện đại hóa","Xóa bỏ ngay lập tức toàn bộ kinh tế tư nhân trong nước","Dùng bạo lực trấn áp mọi tầng lớp có nhiều tài sản","Hạn chế tối đa giao lưu và hội nhập kinh tế quốc tế"],"a":[0],"e":"Văn kiện của Đảng (Đại hội IX trở đi): nội dung chủ yếu của đấu tranh giai cấp trong giai đoạn hiện nay là thực hiện thắng lợi sự nghiệp công nghiệp hóa, hiện đại hóa theo định hướng xã hội chủ nghĩa, khắc phục tình trạng nước nghèo, kém phát triển; thực hiện công bằng xã hội, chống áp bức, bất công… Giáo trình tóm lại: thực hiện thắng lợi mục tiêu độc lập dân tộc và chủ nghĩa xã hội, dân giàu, nước mạnh, dân chủ, công bằng, văn minh.","w":["","Kinh tế tư nhân là một động lực quan trọng của nền kinh tế; «xóa bỏ ngay» trái đường lối.","Không phải đấu tranh bằng bạo lực với người có tài sản hợp pháp.","Đường lối là chủ động hội nhập quốc tế."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.1 (Vấn đề giai cấp và đấu tranh giai cấp); Văn kiện Đại hội IX (2001)","c":5,"v":"khớp","id":"dv-II.17","p":2,"t":"Trắc nghiệm"},
{"q":"Theo Lênin, tập đoàn người này có thể chiếm đoạt lao động của tập đoàn người khác là do các tập đoàn đó:","o":["Có địa vị khác nhau trong một chế độ kinh tế","Có sức khỏe và trí tuệ bẩm sinh khác hẳn nhau","Có phong tục tập quán và nơi sinh sống khác nhau","Có tôn giáo, tín ngưỡng và lối sống khác nhau"],"a":[0],"e":"Theo định nghĩa của Lênin trong «Sáng kiến vĩ đại»: giai cấp là những tập đoàn người mà tập đoàn này có thể chiếm đoạt lao động của tập đoàn khác, do chỗ các tập đoàn đó có địa vị khác nhau trong một chế độ kinh tế - xã hội nhất định.","w":["","Yếu tố bẩm sinh không tạo nên giai cấp.","Phong tục, nơi ở là đặc điểm tộc người, không phải cơ sở của bóc lột.","Tôn giáo, lối sống không phải cơ sở định nghĩa giai cấp."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.1 (Vấn đề giai cấp và đấu tranh giai cấp)","c":5,"v":"khớp","id":"dv-II.18","p":2,"t":"Trắc nghiệm"},
{"q":"\"Ngày nay xã hội đã hiện đại, nên lý luận về giai cấp hết giá trị.\" Theo quan điểm mácxít, nhận định này sai vì:","o":["Giai cấp còn tồn tại khi còn cơ sở kinh tế của nó","Giai cấp sẽ tồn tại vĩnh viễn trong mọi xã hội loài người","Giai cấp chỉ tồn tại trong xã hội phong kiến","Giai cấp do ý muốn của nhà nước tạo ra"],"a":[0],"e":"Giai cấp gắn với những giai đoạn lịch sử nhất định của sản xuất: còn chế độ tư hữu và cơ sở kinh tế của nó thì giai cấp và đấu tranh giai cấp còn tồn tại. Xã hội «hiện đại» hay không không phải tiêu chí.","w":["","Giai cấp không vĩnh viễn; nó sẽ mất khi cơ sở kinh tế của nó mất.","Giai cấp tồn tại trong mọi xã hội có tư hữu (chủ nô, phong kiến, tư bản…), không chỉ phong kiến.","Giai cấp có nguồn gốc kinh tế khách quan, không do nhà nước tạo ra."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.1 (Vấn đề giai cấp và đấu tranh giai cấp)","c":5,"v":"khớp","id":"dv-II.19","p":2,"t":"Tìm lỗi lập luận"},
{"q":"\"Đã bàn về dân tộc thì không cần quan tâm đến lợi ích giai cấp, và ngược lại.\" Lỗi của lập luận này là:","o":["Tách rời hai vấn đề vốn gắn bó biện chứng","Đánh giá đúng tính độc lập của từng vấn đề","Coi vấn đề dân tộc quyết định vấn đề giai cấp","Chỉ thấy mặt kinh tế mà bỏ qua mặt chính trị"],"a":[0],"e":"Giai cấp và dân tộc gắn bó biện chứng: vấn đề giai cấp quyết định khuynh hướng giải quyết vấn đề dân tộc, còn giải phóng dân tộc là điều kiện để giải phóng giai cấp. Tách rời hai vấn đề là sai lầm siêu hình.","w":["","Hai vấn đề chỉ độc lập tương đối, không thể bàn riêng rẽ.","Lập luận không khẳng định dân tộc quyết định giai cấp.","Lập luận không nói tới cặp kinh tế – chính trị."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.3 (Mối quan hệ giai cấp - dân tộc - nhân loại)","c":5,"v":"khớp","id":"dv-II.20","p":2,"t":"Tìm lỗi lập luận"},
{"q":"Một bài đăng viết: \"Người giàu đều là kẻ bóc lột, người nghèo đều là người bị bóc lột.\" Theo quan điểm mácxít, lập luận này sai ở chỗ:","o":["Đồng nhất giai cấp với mức giàu nghèo bề ngoài","Thừa nhận trong xã hội có sự phân hóa giàu nghèo","Đề cao vai trò của người lao động trong xã hội","Cho rằng giai cấp gắn với quan hệ sản xuất"],"a":[0],"e":"Giàu – nghèo chỉ là biểu hiện bề ngoài. Tiêu chí xác định giai cấp là địa vị trong hệ thống sản xuất, trước hết là quan hệ đối với tư liệu sản xuất (có bóc lột lao động người khác hay không). Có người giàu nhờ lao động, sáng tạo chính đáng.","w":["","Thừa nhận phân hóa giàu nghèo là đúng thực tế, không phải lỗi.","Bài đăng không đề cao người lao động.","Cho rằng giai cấp gắn với quan hệ sản xuất là đúng quan điểm mácxít, nhưng bài đăng không nói vậy."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.1 (Vấn đề giai cấp và đấu tranh giai cấp)","c":5,"v":"khớp","id":"dv-II.21","p":2,"t":"Tìm lỗi lập luận"},
{"q":"\"Muốn xóa bỏ áp bức dân tộc, chỉ cần kêu gọi các dân tộc đoàn kết, không cần thay đổi cơ sở kinh tế.\" Hạn chế của quan điểm này là:","o":["Bỏ qua nguồn gốc kinh tế, giai cấp của áp bức","Đề cao đúng mức vai trò của đoàn kết các dân tộc","Cho rằng áp bức dân tộc có nguồn gốc kinh tế","Thừa nhận dân tộc có lợi ích riêng"],"a":[0],"e":"Áp bức giai cấp là nguồn gốc sâu xa của áp bức dân tộc. Kêu gọi đoàn kết là cần nhưng không đủ nếu cơ sở kinh tế – giai cấp của áp bức vẫn còn: «xóa bỏ tình trạng người bóc lột người thì tình trạng dân tộc này bóc lột dân tộc khác cũng sẽ bị xóa bỏ».","w":["","Quan điểm này đề cao đoàn kết một cách phiến diện, không phải «đúng mức».","Quan điểm này bỏ qua, chứ không thừa nhận, nguồn gốc kinh tế.","Không phải chỗ hạn chế; thừa nhận lợi ích dân tộc là đúng."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.3 (Mối quan hệ giai cấp - dân tộc - nhân loại)","c":5,"v":"khớp","id":"dv-II.22","p":2,"t":"Tìm lỗi lập luận"},
{"q":"Trên mạng xã hội xuất hiện các bài viết kích động kỳ thị vùng miền, gây chia rẽ cộng đồng. Theo quan điểm về dân tộc, đây là hành vi:","o":["Làm suy yếu khối đại đoàn kết dân tộc","Thể hiện tính kế thừa của ý thức xã hội","Góp phần củng cố bản sắc từng địa phương","Phản ánh đúng đặc trưng của cộng đồng dân tộc"],"a":[0],"e":"Dân tộc Việt Nam là cộng đồng thống nhất trong đa dạng; đoàn kết là truyền thống quý báu và nguồn sức mạnh. Kích động kỳ thị vùng miền làm tổn hại sự thống nhất về văn hóa, tâm lý — làm suy yếu khối đại đoàn kết dân tộc.","w":["","Kế thừa là tiếp nối giá trị tích cực; kỳ thị không phải biểu hiện đó.","Bản sắc địa phương được củng cố bằng giao lưu, tôn trọng, không phải bằng chia rẽ.","Đặc trưng của dân tộc là thống nhất về văn hóa, tâm lý; kỳ thị đi ngược đặc trưng này."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.2 (Dân tộc)","c":5,"v":"khớp","id":"dv-II.23","p":2,"t":"Tình huống thời sự"},
{"q":"Nhiều quốc gia dùng thuế quan, hạn chế xuất khẩu công nghệ để bảo vệ lợi ích của mình. Điều này cho thấy quan hệ giữa các dân tộc ngày nay:","o":["Vẫn bị lợi ích kinh tế chi phối sâu sắc","Đã hoàn toàn không còn cạnh tranh, xung đột","Chỉ do yếu tố văn hóa, tôn giáo quyết định","Không liên quan gì đến lợi ích các giai cấp"],"a":[0],"e":"Thuế quan, hạn chế xuất khẩu công nghệ cho thấy quan hệ giữa các quốc gia – dân tộc ngày nay vẫn bị lợi ích kinh tế (gắn với lợi ích của giai cấp cầm quyền) chi phối sâu sắc, dù trong bối cảnh toàn cầu hóa.","w":["","Ngược thực tế: cạnh tranh, xung đột lợi ích vẫn diễn ra.","Văn hóa, tôn giáo có ảnh hưởng nhưng không phải nhân tố quyết định ở đây.","Lợi ích dân tộc luôn gắn với lợi ích giai cấp cầm quyền."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.3 (Mối quan hệ giai cấp - dân tộc - nhân loại)","c":5,"v":"khớp","id":"dv-II.24","p":2,"t":"Tình huống thời sự"},
{"q":"Phong trào khởi nghiệp sáng tạo giúp nhiều người trẻ trở thành chủ doanh nghiệp nhỏ. Hiện tượng này phản ánh:","o":["Sự biến đổi, đa dạng của cơ cấu xã hội - giai cấp","Sự biến mất hoàn toàn của mọi giai cấp trong xã hội","Giai cấp được quyết định bởi độ tuổi và thế hệ","Đấu tranh giai cấp đã chấm dứt vĩnh viễn ở mọi nơi"],"a":[0],"e":"Kết cấu xã hội - giai cấp luôn biến đổi theo cơ cấu kinh tế. Trong nền kinh tế thị trường nhiều thành phần, xuất hiện thêm các tầng lớp mới như doanh nhân trẻ, chủ doanh nghiệp nhỏ — cơ cấu xã hội - giai cấp đa dạng hơn.","w":["","Giai cấp không biến mất chỉ vì có thêm tầng lớp mới.","Tuổi tác, thế hệ không phải tiêu chí xác định giai cấp.","Giáo trình khẳng định ở Việt Nam hiện nay vẫn còn đấu tranh giai cấp."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục II.1 (Vấn đề giai cấp và đấu tranh giai cấp)","c":5,"v":"khớp","id":"dv-II.25","p":2,"t":"Tình huống thời sự"},
{"q":"Theo V.I. Lênin, nhà nước là sản phẩm và biểu hiện của:","o":["Khế ước xã hội giữa các công dân","Nhu cầu quản lý công việc chung của cộng đồng","Ý chí của lực lượng siêu nhiên","Mâu thuẫn giai cấp không thể điều hòa"],"a":[3],"e":"Trong «Nhà nước và cách mạng» (1917), Lênin viết: nhà nước là sản phẩm và biểu hiện của những mâu thuẫn giai cấp không thể điều hòa được. Ở đâu và lúc nào mâu thuẫn giai cấp không thể điều hòa thì nhà nước xuất hiện.","w":["«Khế ước xã hội» là quan điểm của các nhà tư tưởng tư sản (Rútxô…), che giấu bản chất giai cấp của nhà nước.","Quản lý công việc chung đã có từ thị tộc, bộ lạc (chưa có nhà nước); đây không phải nguồn gốc của nhà nước.","Quan điểm thần học, duy tâm.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.1 (Nhà nước); V.I. Lênin, «Nhà nước và cách mạng» (1917)","c":5,"v":"khớp","id":"dv-III.1","p":3,"t":"Trắc nghiệm"},
{"q":"Về bản chất, nhà nước là:","o":["Công cụ duy trì sự thống trị của một giai cấp","Cơ quan đứng trên các giai cấp, điều hòa lợi ích","Tổ chức tự quản đại diện cho toàn thể cộng đồng","Bộ máy đại diện đều cho mọi tầng lớp xã hội"],"a":[0],"e":"Về bản chất, nhà nước là công cụ thống trị của giai cấp thống trị về kinh tế (giai cấp nắm tư liệu sản xuất chủ yếu), dùng để duy trì sự thống trị và trấn áp sự phản kháng của các giai cấp khác.","w":["","Quan điểm «nhà nước siêu giai cấp» che giấu bản chất giai cấp của nhà nước.","Tổ chức tự quản của toàn cộng đồng là đặc điểm của thị tộc, bộ lạc, không phải nhà nước.","Nhà nước không đại diện đều cho mọi tầng lớp; nó mang bản chất giai cấp."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.1 (Nhà nước)","c":5,"v":"khớp","id":"dv-III.2","p":3,"t":"Trắc nghiệm"},
{"q":"Đặc trưng nào sau đây KHÔNG phải là đặc trưng của nhà nước?","o":["Quản lý dân cư theo đơn vị lãnh thổ","Có bộ máy quyền lực mang tính cưỡng chế","Quản lý dân cư theo quan hệ huyết thống","Có hệ thống thuế khóa để nuôi bộ máy"],"a":[2],"e":"Giáo trình (theo Ăngghen) nêu ba đặc trưng cơ bản của nhà nước: (1) quản lý cư dân trên một vùng lãnh thổ nhất định; (2) có hệ thống cơ quan quyền lực chuyên nghiệp mang tính cưỡng chế; (3) có hệ thống thuế khóa để nuôi bộ máy. Quản lý theo huyết thống là đặc điểm của thị tộc, bộ lạc.","w":["Đây là đặc trưng thứ nhất của nhà nước.","Đây là đặc trưng thứ hai của nhà nước.","","Đây là đặc trưng thứ ba của nhà nước."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.1 (c. Đặc trưng cơ bản của nhà nước)","c":5,"v":"khớp","id":"dv-III.3","p":3,"t":"Trắc nghiệm","k":"Giáo trình Triết học nêu 3 đặc trưng; đề cũ (câu 474) lại chọn «năm đặc trưng» theo cách nêu của môn Lý luận nhà nước và pháp luật. Câu này hỏi đặc trưng KHÔNG thuộc nhà nước nên không bị ảnh hưởng."},
{"q":"Trong các chức năng của nhà nước, chức năng giữ vai trò chi phối là:","o":["Chức năng xã hội, quản lý công việc chung","Chức năng thống trị chính trị","Chức năng đối ngoại","Chức năng quản lý kinh tế"],"a":[1],"e":"Giáo trình: nhà nước có chức năng thống trị chính trị của giai cấp và chức năng xã hội (cũng như đối nội, đối ngoại). «Do bản chất giai cấp của nhà nước qui định, nhà nước bao giờ cũng đặt chức năng thống trị chính trị của giai cấp lên hàng đầu» — nó chi phối các chức năng khác.","w":["Chức năng xã hội vẫn chịu sự chi phối của chức năng thống trị chính trị.","","Đối ngoại là một chiều phân loại khác (đối nội/đối ngoại), không giữ vai trò chi phối.","Quản lý kinh tế là một nội dung của chức năng xã hội."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.1 (d. Chức năng cơ bản của nhà nước)","c":5,"v":"khớp","id":"dv-III.4","p":3,"t":"Trắc nghiệm"},
{"q":"Kiểu nhà nước được gọi là \"nhà nước kiểu mới\", \"nhà nước nửa nhà nước\" là:","o":["Nhà nước vô sản","Nhà nước tư sản","Nhà nước phong kiến","Nhà nước chủ nô"],"a":[0],"e":"Lênin (trong «Nhà nước và cách mạng») gọi nhà nước vô sản là «nhà nước kiểu mới», «nửa nhà nước» vì nó là nhà nước của đa số nhân dân lao động và tự tạo điều kiện cho sự tiêu vong của chính mình. Giáo trình: nhà nước vô sản là «nhà nước đặc biệt, nhà nước của số đông thống trị số ít».","w":["","Nhà nước tư sản vẫn là công cụ của thiểu số bóc lột.","Nhà nước phong kiến là công cụ của địa chủ, quý tộc.","Nhà nước chủ nô là kiểu nhà nước đầu tiên, của thiểu số chủ nô."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.1 (kiểu nhà nước); V.I. Lênin, «Nhà nước và cách mạng»","c":5,"v":"khớp","id":"dv-III.5","p":3,"t":"Trắc nghiệm"},
{"q":"Theo nghĩa RỘNG, cách mạng xã hội là:","o":["Sự thay đổi nhân sự lãnh đạo trong bộ máy nhà nước","Cuộc cải cách từng mặt riêng lẻ của đời sống xã hội","Bước chuyển từ hình thái kinh tế - xã hội thấp lên cao","Việc lật đổ chính quyền của giai cấp thống trị lỗi thời"],"a":[2],"e":"Giáo trình: theo nghĩa rộng, cách mạng xã hội là sự thay đổi căn bản về chất toàn bộ các lĩnh vực đời sống xã hội, là phương thức chuyển từ một hình thái kinh tế - xã hội này lên hình thái mới tiến bộ hơn. Theo nghĩa hẹp, đó là đỉnh cao của đấu tranh giai cấp, lật đổ chính quyền, thiết lập chính quyền mới tiến bộ hơn.","w":["Thay nhân sự lãnh đạo giữ nguyên chế độ gần với đảo chính, không phải cách mạng.","Thay đổi từng mặt riêng lẻ là cải cách xã hội.","","Lật đổ chính quyền của giai cấp thống trị lỗi thời là nghĩa HẸP."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.2 (Cách mạng xã hội)","c":5,"v":"khớp","id":"dv-III.6","p":3,"t":"Trắc nghiệm"},
{"q":"Nguyên nhân sâu xa của cách mạng xã hội là:","o":["Sự bất mãn của tầng lớp trí thức tiến bộ","Mâu thuẫn giữa lực lượng sản xuất và quan hệ sản xuất","Sự can thiệp, áp đặt từ các thế lực chính trị bên ngoài","Mâu thuẫn giữa giai cấp thống trị và bị trị"],"a":[1],"e":"Giáo trình: cách mạng xã hội có nguồn gốc sâu xa là mâu thuẫn giữa lực lượng sản xuất tiến bộ đòi hỏi được giải phóng với quan hệ sản xuất đã lỗi thời. Mâu thuẫn giai cấp là biểu hiện về mặt xã hội của mâu thuẫn kinh tế đó.","w":["Bất mãn của trí thức là yếu tố chủ quan, bề mặt.","","Can thiệp bên ngoài không phải nguồn gốc của cách mạng xã hội.","Mâu thuẫn giai cấp là biểu hiện xã hội, không phải nguyên nhân sâu xa."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.2 (a. Nguồn gốc của cách mạng xã hội)","c":5,"v":"khớp","id":"dv-III.7","p":3,"t":"Trắc nghiệm"},
{"q":"Vấn đề cơ bản của mọi cuộc cách mạng xã hội là:","o":["Vấn đề chính quyền nhà nước","Vấn đề ruộng đất cho nông dân","Vấn đề lực lượng vũ trang","Vấn đề tư tưởng, văn hóa"],"a":[0],"e":"Lênin: vấn đề cơ bản của mọi cuộc cách mạng là vấn đề chính quyền nhà nước. Giáo trình: đặc trưng của cách mạng là chuyển chính quyền sang tay giai cấp cách mạng; có chính quyền mới cải tạo được xã hội cũ.","w":["","Ruộng đất là nội dung quan trọng của cách mạng dân chủ, không phải vấn đề cơ bản của mọi cuộc cách mạng.","Lực lượng vũ trang là công cụ giành, giữ chính quyền, không phải vấn đề cơ bản.","Tư tưởng, văn hóa là nhiệm vụ lâu dài sau khi có chính quyền."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.2 (Cách mạng xã hội)","c":5,"v":"khớp","id":"dv-III.8","p":3,"t":"Trắc nghiệm"},
{"q":"Câu nói \"Các cuộc cách mạng là đầu tàu của lịch sử\" là của:","o":["Hồ Chí Minh","V.I. Lênin","G. Plêkhanốp","C. Mác"],"a":[3],"e":"C. Mác viết «Các cuộc cách mạng là đầu tàu của lịch sử» trong «Đấu tranh giai cấp ở Pháp từ 1848 đến 1850», nhấn mạnh cách mạng là phương thức, động lực đẩy nhanh tiến trình lịch sử.","w":["Không phải câu của Hồ Chí Minh.","Lênin hay trích dẫn ý này nhưng tác giả là Mác.","Plêkhanốp không phải tác giả câu này.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.2 (Cách mạng xã hội); C. Mác, «Đấu tranh giai cấp ở Pháp từ 1848 đến 1850»","c":5,"v":"khớp","id":"dv-III.9","p":3,"t":"Trắc nghiệm"},
{"q":"Theo Lênin, dấu hiệu nào sau đây KHÔNG thuộc tình thế cách mạng?","o":["Giai cấp thống trị không thể thống trị như cũ","Giai cấp thống trị tự nguyện trao quyền lực","Quần chúng khổ cực hơn mức bình thường","Tính tích cực của quần chúng tăng rõ rệt"],"a":[1],"e":"Lênin nêu ba dấu hiệu của tình thế cách mạng: giai cấp thống trị không thể duy trì sự thống trị như cũ (khủng hoảng «tầng lớp trên»); nỗi khốn cùng của quần chúng nặng nề hơn mức bình thường; tính tích cực của quần chúng tăng lên rõ rệt. Giai cấp thống trị không bao giờ tự nguyện trao quyền.","w":["Đây là dấu hiệu thứ nhất của tình thế cách mạng.","","Đây là dấu hiệu thứ hai.","Đây là dấu hiệu thứ ba."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.2 (tình thế cách mạng); V.I. Lênin, «Sự phá sản của Quốc tế II» (1915)","c":5,"v":"khớp","id":"dv-III.10","p":3,"t":"Trắc nghiệm"},
{"q":"Nhà nước tồn tại vĩnh viễn cùng với xã hội loài người.","o":["Đúng","Sai"],"a":[1],"e":"Sai. Nhà nước là phạm trù lịch sử: ra đời khi xã hội phân chia giai cấp và mâu thuẫn giai cấp không thể điều hòa; sẽ tiêu vong khi cơ sở giai cấp của nó không còn. Thời cộng sản nguyên thủy chưa có nhà nước.","w":["Từ «vĩnh viễn» là dấu hiệu nhận định sai.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.1 (Nhà nước)","c":5,"v":"khớp","id":"dv-III.11","p":3,"t":"Đúng/Sai","f":1},
{"q":"Cải cách là sự thay đổi từng mặt của đời sống xã hội, không làm thay đổi bản chất chế độ.","o":["Đúng","Sai"],"a":[0],"e":"Đúng. Giáo trình: «Cải cách xã hội chỉ tạo lên những thay đổi bộ phận, lĩnh vực riêng lẻ của đời sống xã hội», khác với cách mạng xã hội là thay đổi căn bản chế độ. Lưu ý: nhiều khi cải cách là bộ phận hợp thành của cách mạng.","w":["","Đánh đồng cải cách với cách mạng xã hội."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.2 (Cách mạng xã hội)","c":5,"v":"khớp","id":"dv-III.12","p":3,"t":"Đúng/Sai","f":1},
{"q":"Theo Hiến pháp 2013, Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam là nhà nước pháp quyền xã hội chủ nghĩa của Nhân dân, do Nhân dân, vì Nhân dân.","o":["Đúng","Sai"],"a":[0],"e":"Đúng. Khoản 1 Điều 2 Hiến pháp năm 2013: «Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam là nhà nước pháp quyền xã hội chủ nghĩa của Nhân dân, do Nhân dân, vì Nhân dân.»","w":["","Trái với quy định nguyên văn của Hiến pháp 2013."],"s":"Hiến pháp nước CHXHCN Việt Nam năm 2013, Điều 2 khoản 1","c":5,"v":"khớp","id":"dv-III.13","p":3,"t":"Đúng/Sai","f":1},
{"q":"Sắp xếp các kiểu nhà nước theo trình tự lịch sử:\n(1) Nhà nước phong kiến · (2) Nhà nước chủ nô · (3) Nhà nước vô sản · (4) Nhà nước tư sản","o":["2 → 1 → 4 → 3","1 → 2 → 4 → 3","2 → 4 → 1 → 3","2 → 1 → 3 → 4"],"a":[0],"e":"Giáo trình: đã từng tồn tại bốn kiểu nhà nước — chủ nô quý tộc → phong kiến → tư sản → vô sản (nhà nước kiểu mới). Kiểu nhà nước được xác định theo bản chất giai cấp, gắn với các hình thái kinh tế - xã hội có giai cấp.","w":["","Nhà nước chủ nô là kiểu nhà nước đầu tiên, phải đứng trước phong kiến.","Nhà nước tư sản ra đời sau nhà nước phong kiến.","Nhà nước vô sản ra đời sau, thay thế nhà nước tư sản."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.1 (kiểu nhà nước)","c":5,"v":"khớp","id":"dv-III.14","p":3,"t":"Sắp xếp"},
{"q":"Sắp xếp logic dẫn tới một cuộc cách mạng xã hội:\n(1) Mâu thuẫn giai cấp ngày càng gay gắt\n(2) Mâu thuẫn giữa lực lượng sản xuất và quan hệ sản xuất\n(3) Giai cấp cách mạng giành chính quyền\n(4) Xuất hiện tình thế cách mạng","o":["2 → 1 → 4 → 3","1 → 2 → 4 → 3","2 → 4 → 1 → 3","4 → 1 → 2 → 3"],"a":[0],"e":"Mâu thuẫn kinh tế (lực lượng sản xuất – quan hệ sản xuất) (2) biểu hiện thành mâu thuẫn giai cấp ngày càng gay gắt (1); khi chín muồi thì xuất hiện tình thế cách mạng (4); có nhân tố chủ quan đủ mạnh thì giai cấp cách mạng giành chính quyền (3).","w":["","Mâu thuẫn giai cấp là biểu hiện của mâu thuẫn kinh tế, nên không đứng trước nó.","Tình thế cách mạng là sự chín muồi của mâu thuẫn giai cấp, phải đến sau.","Tình thế cách mạng không thể xuất hiện trước khi có mâu thuẫn kinh tế và giai cấp."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.2 (Cách mạng xã hội)","c":5,"v":"khớp","id":"dv-III.15","p":3,"t":"Sắp xếp"},
{"q":"Ghép khái niệm với nội dung:\n1. Cách mạng xã hội · 2. Cải cách · 3. Đảo chính\na. Thay đổi người cầm quyền, giữ nguyên chế độ\nb. Thay đổi căn bản chế độ chính trị và kinh tế\nc. Thay đổi từng mặt, giữ nguyên bản chất chế độ","o":["1-a, 2-b, 3-c","1-b, 2-c, 3-a","1-c, 2-b, 3-a","1-b, 2-a, 3-c"],"a":[1],"e":"Cách mạng xã hội: thay đổi căn bản chế độ chính trị và kinh tế (1-b). Cải cách: thay đổi từng bộ phận, lĩnh vực, giữ nguyên bản chất chế độ (2-c). Đảo chính: một nhóm người giành chính quyền nhưng không làm thay đổi căn bản chế độ xã hội (3-a).","w":["Đảo vị trí: cách mạng không phải chỉ thay người cầm quyền.","","Cách mạng không phải thay đổi từng mặt; cải cách không thay đổi căn bản chế độ.","Cải cách không phải thay người cầm quyền; đảo chính không phải thay đổi từng mặt."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.2 (Cách mạng xã hội)","c":5,"v":"khớp","id":"dv-III.16","p":3,"t":"Ghép đôi"},
{"q":"Theo Lênin, ngoài tình thế cách mạng, cách mạng chỉ nổ ra và thắng lợi khi có thêm:","o":["Sự can thiệp quân sự của các nước bên ngoài","Nhân tố chủ quan đủ sức hành động","Sự đồng thuận của chính giai cấp thống trị","Một cuộc khủng hoảng thiên tai trên diện rộng"],"a":[1],"e":"Tình thế cách mạng là điều kiện khách quan. Giáo trình (dẫn Lênin): không phải tình thế cách mạng nào cũng làm nổ ra cách mạng, mà chỉ khi có thêm nhân tố chủ quan — ý chí, giác ngộ, năng lực tổ chức của giai cấp cách mạng đủ sức hành động. Khi điều kiện khách quan chín muồi, nhân tố chủ quan có vai trò quyết định thành bại.","w":["Can thiệp quân sự bên ngoài không phải điều kiện Lênin nêu.","","Giai cấp thống trị không bao giờ đồng thuận với cách mạng.","Thiên tai có thể làm trầm trọng khủng hoảng nhưng không phải điều kiện cần."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.2 (Cách mạng xã hội)","c":5,"v":"khớp","id":"dv-III.17","p":3,"t":"Trắc nghiệm"},
{"q":"Cách mạng Tháng Tám 1945 nổ ra và thắng lợi khi Nhật đầu hàng Đồng minh, chính quyền tay sai hoang mang. Thành công này cho thấy rõ nhất vai trò của:","o":["Chớp đúng thời cơ cách mạng","Sự giúp đỡ quân sự từ bên ngoài","Sự nhượng bộ tự nguyện của Nhật","Yếu tố ngẫu nhiên, may mắn"],"a":[0],"e":"Giáo trình lấy chính Cách mạng Tháng Tám làm ví dụ: nạn đói hơn 2 triệu người, Nhật đảo chính Pháp, Nhật đầu hàng Đồng minh là tình thế cách mạng. Đảng chớp đúng thời cơ, kết hợp điều kiện khách quan với nhân tố chủ quan đã chuẩn bị lâu dài để tổng khởi nghĩa giành chính quyền.","w":["","Cách mạng Tháng Tám do nhân dân ta tự lực giành chính quyền.","Nhật không tự nguyện nhượng bộ; nhân dân ta khởi nghĩa giành chính quyền.","Thắng lợi là kết quả chuẩn bị lâu dài và chớp thời cơ, không phải may mắn."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.2 (tình thế cách mạng – ví dụ Cách mạng Tháng Tám)","c":5,"v":"khớp","id":"dv-III.18","p":3,"t":"Trắc nghiệm"},
{"q":"Chức năng xã hội của nhà nước thể hiện ở hoạt động:","o":["Quản lý công việc chung: y tế, giáo dục","Đàn áp sự phản kháng của giai cấp đối lập","Tiến hành chiến tranh xâm lược nước khác","Bảo vệ đặc quyền riêng của tầng lớp cầm quyền"],"a":[0],"e":"Giáo trình: chức năng xã hội là nhà nước nhân danh xã hội điều hành các công việc chung như thủy lợi, giao thông, y tế, giáo dục, bảo vệ môi trường… Trong nhà nước có giai cấp, chức năng này vẫn chịu sự chi phối của chức năng thống trị chính trị.","w":["","Đàn áp sự phản kháng là chức năng thống trị chính trị.","Chiến tranh xâm lược là biểu hiện (tiêu cực) của chức năng đối ngoại.","Bảo vệ đặc quyền của giai cấp cầm quyền thuộc chức năng thống trị chính trị."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.1 (d. Chức năng cơ bản của nhà nước)","c":5,"v":"khớp","id":"dv-III.19","p":3,"t":"Trắc nghiệm"},
{"q":"\"Nhà nước là trọng tài trung lập đứng trên mọi giai cấp.\" Theo chủ nghĩa duy vật lịch sử, quan điểm này:","o":["Che giấu bản chất giai cấp của nhà nước","Phản ánh đúng bản chất của mọi nhà nước","Chỉ đúng với nhà nước chủ nô","Đúng, vì nhà nước có chức năng xã hội"],"a":[0],"e":"Nhà nước có chức năng xã hội thật, nhưng là đại biểu của toàn xã hội «chỉ trong chừng mực nó là nhà nước của bản thân giai cấp đại diện cho toàn xã hội» (Ăngghen). Coi nhà nước là trọng tài trung lập đứng trên giai cấp là che giấu bản chất giai cấp của nó.","w":["","Không nhà nước nào đứng trên các giai cấp.","Mọi kiểu nhà nước trong lịch sử đều mang bản chất giai cấp, không riêng nhà nước chủ nô.","Chức năng xã hội không làm mất bản chất giai cấp; nó bị chức năng thống trị chính trị chi phối."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.1 (Nhà nước)","c":5,"v":"khớp","id":"dv-III.20","p":3,"t":"Tìm lỗi lập luận"},
{"q":"\"Cách mạng có thể nổ ra bất cứ lúc nào, chỉ cần có một nhóm người đủ quyết tâm.\" Lập luận này mắc lỗi:","o":["Chủ quan duy ý chí, bỏ qua tình thế cách mạng","Đánh giá đúng vai trò của nhân tố chủ quan","Tuyệt đối hóa điều kiện khách quan của cách mạng","Đồng nhất cách mạng xã hội với cải cách"],"a":[0],"e":"Quyết tâm (nhân tố chủ quan) là cần, nhưng «không có tình thế cách mạng thì cách mạng xã hội không thể nổ ra được» (giáo trình). Hành động bất chấp điều kiện khách quan là chủ quan duy ý chí, phiêu lưu.","w":["","Lập luận tuyệt đối hóa, không đánh giá đúng nhân tố chủ quan.","Ngược lại: lập luận bỏ qua điều kiện khách quan.","Lập luận không nhầm cách mạng với cải cách."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.2 (Cách mạng xã hội)","c":5,"v":"khớp","id":"dv-III.21","p":3,"t":"Tìm lỗi lập luận"},
{"q":"\"Đã có tình thế cách mạng thì cách mạng chắc chắn tự nổ ra và thắng lợi.\" Lập luận này sai vì:","o":["Xem nhẹ vai trò của nhân tố chủ quan","Đề cao quá mức vai trò của lãnh tụ","Phủ nhận điều kiện khách quan của cách mạng","Đồng nhất nhà nước với chính phủ"],"a":[0],"e":"Theo Lênin, không phải tình thế cách mạng nào cũng dẫn tới cách mạng; cần nhân tố chủ quan đủ sức tiến hành hành động cách mạng. Đây là lỗi ngược với chủ quan duy ý chí: tuyệt đối hóa điều kiện khách quan, xem nhẹ nhân tố chủ quan.","w":["","Lập luận không đề cập lãnh tụ.","Lập luận tuyệt đối hóa, chứ không phủ nhận, điều kiện khách quan.","Lập luận không đề cập nhà nước hay chính phủ."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.2 (Cách mạng xã hội)","c":5,"v":"khớp","id":"dv-III.22","p":3,"t":"Tìm lỗi lập luận"},
{"q":"\"Cải cách chậm quá, cứ đập bỏ tất cả rồi làm lại từ đầu mới nhanh.\" Theo quan điểm biện chứng về phát triển xã hội, sai lầm ở đây là:","o":["Phủ định sạch trơn, không kế thừa yếu tố hợp lý","Đánh giá đúng vai trò của cách mạng xã hội","Đề cao tính kế thừa trong sự phát triển","Tuyệt đối hóa vai trò của những cải cách từng bước"],"a":[0],"e":"Phủ định biện chứng luôn có tính kế thừa: giữ lại những yếu tố hợp lý của cái cũ. «Đập bỏ tất cả» là phủ định sạch trơn (phủ định siêu hình), đồng thời là tư duy nóng vội, chủ quan. Giáo trình cũng chỉ rõ cải cách có thể là bộ phận của cách mạng.","w":["","Cách mạng xã hội không có nghĩa là phá bỏ tất cả.","Lập luận phủ nhận, chứ không đề cao, tính kế thừa.","Lập luận coi thường, chứ không tuyệt đối hóa, cải cách từng bước."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.2 (Cách mạng xã hội); Ch.2, mục II (quy luật phủ định của phủ định)","c":5,"v":"khớp","id":"dv-III.23","p":3,"t":"Tìm lỗi lập luận"},
{"q":"Chính phủ điện tử, dịch vụ công trực tuyến giúp người dân làm thủ tục mà không cần đến cơ quan nhà nước. Điều này thể hiện rõ nhất:","o":["Đổi mới cách thực hiện chức năng xã hội","Sự tiêu vong của nhà nước trong thời đại số","Nhà nước không còn mang bản chất giai cấp","Một cuộc cách mạng xã hội theo nghĩa rộng"],"a":[0],"e":"Chính phủ điện tử, dịch vụ công trực tuyến là đổi mới phương thức nhà nước điều hành công việc chung, phục vụ người dân — tức đổi mới cách thực hiện chức năng xã hội. Nhà nước vẫn tồn tại và vẫn mang bản chất giai cấp.","w":["","Nhà nước chỉ tiêu vong khi cơ sở giai cấp không còn, không phải nhờ công nghệ.","Công nghệ không làm thay đổi bản chất giai cấp của nhà nước.","Không có sự thay thế hình thái kinh tế - xã hội nào ở đây."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.1 (chức năng xã hội)","c":5,"v":"khớp","id":"dv-III.24","p":3,"t":"Tình huống thời sự"},
{"q":"Cuộc cách mạng công nghiệp lần thứ tư thường được gọi là \"cách mạng\". Theo nghĩa triết học, nó khác cách mạng xã hội ở chỗ:","o":["Nó biến đổi lực lượng sản xuất, chưa đổi chế độ xã hội","Nó trực tiếp lật đổ chính quyền của giai cấp thống trị","Nó không làm thay đổi gì trong sản xuất xã hội","Nó chỉ diễn ra trong lĩnh vực văn hóa, nghệ thuật"],"a":[0],"e":"Cách mạng công nghiệp là bước nhảy vọt về lực lượng sản xuất (khoa học, công nghệ). Cách mạng xã hội là thay đổi căn bản hình thái kinh tế - xã hội, mà đặc trưng là chuyển chính quyền. Cách mạng công nghiệp có thể tạo tiền đề cho biến đổi xã hội nhưng không đồng nhất với nó.","w":["","Cách mạng công nghiệp không trực tiếp lật đổ chính quyền.","Nó làm biến đổi sâu sắc lực lượng sản xuất.","Nó diễn ra chủ yếu trong sản xuất, không chỉ văn hóa, nghệ thuật."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục III.2 (Cách mạng xã hội); Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-III.25","p":3,"t":"Tình huống thời sự"},
{"q":"Hiến pháp 2013 quy định quyền lực nhà nước là thống nhất, có sự phân công, phối hợp và kiểm soát giữa các cơ quan. Mục đích chủ yếu của cơ chế kiểm soát quyền lực là:","o":["Phòng ngừa lạm quyền, bảo đảm quyền lực của nhân dân","Chia nhà nước thành các phe phái đối lập, kiềm chế lẫn nhau","Tăng thêm số cơ quan, đơn vị để giải quyết việc làm","Chuyển toàn bộ quyền lực sang các tổ chức tư nhân"],"a":[0],"e":"Khoản 3 Điều 2 Hiến pháp 2013: quyền lực nhà nước là thống nhất, có sự phân công, phối hợp, kiểm soát giữa các cơ quan trong thực hiện quyền lập pháp, hành pháp, tư pháp. Mục đích của kiểm soát quyền lực là phòng ngừa lạm quyền, bảo đảm quyền lực nhà nước thuộc về Nhân dân.","w":["","Quyền lực nhà nước Việt Nam là thống nhất, không chia thành các phe đối lập (khác mô hình «tam quyền phân lập»).","Không phải mục đích của cơ chế kiểm soát quyền lực.","Quyền lực nhà nước thuộc về Nhân dân, không chuyển cho tư nhân."],"s":"Hiến pháp nước CHXHCN Việt Nam năm 2013, Điều 2 khoản 3","c":5,"v":"khớp","id":"dv-III.26","p":3,"t":"Tình huống thời sự"},
{"q":"Tồn tại xã hội là:","o":["Toàn bộ đời sống tinh thần và văn hóa của xã hội","Toàn bộ hệ thống chính trị, pháp luật của xã hội","Sinh hoạt vật chất và điều kiện sinh hoạt vật chất","Toàn bộ dân cư cùng sinh sống trên một lãnh thổ nhất định"],"a":[2],"e":"Giáo trình: tồn tại xã hội là toàn bộ sinh hoạt vật chất và những điều kiện sinh hoạt vật chất của xã hội. Các yếu tố cơ bản: phương thức sản xuất vật chất, điều kiện tự nhiên – hoàn cảnh địa lý, dân số và mật độ dân số.","w":["Đời sống tinh thần, văn hóa là ý thức xã hội — mặt đối lập với tồn tại xã hội.","Chính trị, pháp luật thuộc kiến trúc thượng tầng, không phải tồn tại xã hội.","","Dân cư chỉ là một yếu tố (dân số, mật độ dân số) của tồn tại xã hội, chưa đầy đủ."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.1 (Tồn tại xã hội)","c":5,"v":"khớp","id":"dv-IV.1","p":4,"t":"Trắc nghiệm"},
{"q":"Trong các yếu tố của tồn tại xã hội, yếu tố giữ vai trò quyết định là:","o":["Phương thức sản xuất vật chất","Điều kiện tự nhiên và hoàn cảnh địa lý","Dân số và mật độ dân số","Khí hậu và tài nguyên"],"a":[0],"e":"Trong các yếu tố của tồn tại xã hội, phương thức sản xuất vật chất là yếu tố cơ bản, quyết định: nó quyết định cách con người khai thác tự nhiên, quy mô dân số và tổ chức mọi mặt đời sống xã hội.","w":["","Điều kiện tự nhiên là điều kiện thường xuyên, có thể làm sản xuất nhanh hay chậm nhưng không quyết định.","Dân số ảnh hưởng tới sản xuất nhưng không quyết định.","Khí hậu, tài nguyên thuộc điều kiện tự nhiên — không phải yếu tố quyết định."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.1 (b. Các yếu tố cơ bản của tồn tại xã hội)","c":5,"v":"khớp","id":"dv-IV.2","p":4,"t":"Trắc nghiệm"},
{"q":"\"Không phải ý thức của con người quyết định tồn tại của họ; trái lại, tồn tại xã hội của họ quyết định ý thức của họ.\" Luận điểm này thể hiện lập trường:","o":["Duy tâm khách quan","Duy tâm chủ quan","Nhị nguyên luận","Duy vật lịch sử"],"a":[3],"e":"Luận điểm của C. Mác trong Lời tựa «Góp phần phê phán khoa kinh tế chính trị» (1859): tồn tại xã hội quyết định ý thức xã hội — nguyên lý nền tảng của chủ nghĩa duy vật lịch sử.","w":["Duy tâm khách quan coi «ý niệm tuyệt đối» quyết định, ngược với luận điểm.","Duy tâm chủ quan coi ý thức cá nhân quyết định, ngược với luận điểm.","Nhị nguyên luận coi vật chất và ý thức song song, không cái nào quyết định.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (d. Quan hệ biện chứng giữa tồn tại xã hội và ý thức xã hội); C. Mác, «Góp phần phê phán khoa kinh tế chính trị», Lời tựa (1859)","c":5,"v":"khớp","id":"dv-IV.3","p":4,"t":"Trắc nghiệm"},
{"q":"Căn cứ vào việc tri thức, quan niệm đã được hệ thống hóa, khái quát hóa thành học thuyết hay chưa, ý thức xã hội được chia thành:","o":["Ý thức cá nhân và ý thức của cả tập thể","Ý thức thông thường và ý thức lý luận","Ý thức chính trị và ý thức pháp quyền","Ý thức tiến bộ và ý thức lạc hậu"],"a":[1],"e":"Giáo trình: ý thức thông thường là tri thức, quan niệm hình thành trực tiếp trong hoạt động hằng ngày, chưa được hệ thống hóa, khái quát hóa; ý thức lý luận (ý thức khoa học) là tư tưởng, quan điểm đã được tổng hợp, hệ thống hóa, khái quát hóa thành học thuyết. Ý thức thông thường ở trình độ thấp hơn nhưng phong phú hơn, là chất liệu cho ý thức lý luận.","w":["Ý thức cá nhân và ý thức xã hội là quan hệ cái riêng – cái chung, không phải tiêu chí «đã hệ thống hóa hay chưa».","","Chính trị, pháp quyền là các hình thái ý thức xã hội (chia theo lĩnh vực phản ánh).","Tiến bộ/lạc hậu là đánh giá vai trò, không phải cách chia kết cấu."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (b. Kết cấu của ý thức xã hội)","c":5,"v":"dễ nhầm","id":"dv-IV.4","p":4,"t":"Trắc nghiệm","k":"Đã sửa đề: bản gốc hỏi «xét theo TRÌNH ĐỘ» và coi «tâm lý xã hội – hệ tư tưởng» là phương án sai (vì là «cấp độ»). Nhưng giáo trình không phân biệt hai nhãn này — chính giáo trình viết «ở trình độ tâm lý xã hội… ở trình độ hệ tư tưởng», và đề cũ (câu 413) chọn «hai trình độ: tâm lý xã hội và hệ tư tưởng». Nhớ: ý thức xã hội có HAI cách chia — thông thường/lý luận và tâm lý xã hội/hệ tư tưởng; đề hỏi «hai trình độ» mà chỉ có một cặp thì chọn cặp đó."},
{"q":"Điểm khác nhau cơ bản giữa tâm lý xã hội và hệ tư tưởng là:","o":["Tâm lý xã hội tự phát, hệ tư tưởng tự giác","Tâm lý xã hội có tính khoa học cao hơn hệ tư tưởng","Hệ tư tưởng chỉ có trong xã hội không có giai cấp","Hai cấp độ giống nhau, chỉ khác tên gọi"],"a":[0],"e":"Giáo trình: tâm lý xã hội phản ánh trực tiếp và tự phát điều kiện sinh hoạt hằng ngày (tình cảm, tâm trạng, thói quen, phong tục…), chỉ ghi lại cái bề mặt. Hệ tư tưởng là giai đoạn phát triển cao hơn, là sự nhận thức lý luận, tự giác về tồn tại xã hội, đi sâu vào bản chất các quan hệ xã hội.","w":["","Ngược lại: hệ tư tưởng (khoa học) mới có khả năng phản ánh bản chất; tâm lý xã hội chỉ ghi lại bề mặt.","Hệ tư tưởng mang tính giai cấp rõ nhất trong xã hội có giai cấp.","Hai trình độ khác nhau về chất, không chỉ khác tên."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (b. Kết cấu của ý thức xã hội)","c":5,"v":"khớp","id":"dv-IV.5","p":4,"t":"Trắc nghiệm","k":"Đã bỏ cụm «Xét theo cấp độ» ở đầu đề gốc: giáo trình không gán nhãn «cấp độ» cho cặp này (xem câu IV.4)."},
{"q":"Biểu hiện nào sau đây KHÔNG thuộc tính độc lập tương đối của ý thức xã hội?","o":["Thường lạc hậu so với tồn tại xã hội","Có thể vượt trước tồn tại xã hội","Biến đổi ngay khi tồn tại xã hội biến đổi","Có tính kế thừa trong quá trình phát triển của nó"],"a":[2],"e":"Tính độc lập tương đối của ý thức xã hội gồm: thường lạc hậu so với tồn tại xã hội; có thể vượt trước; có tính kế thừa; các hình thái tác động qua lại; tác động trở lại tồn tại xã hội. «Biến đổi ngay khi tồn tại xã hội biến đổi» là phủ nhận tính độc lập tương đối.","w":["Đây là biểu hiện thứ nhất của tính độc lập tương đối.","Đây là biểu hiện của tư tưởng khoa học tiên tiến.","","Tính kế thừa là một biểu hiện của tính độc lập tương đối."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (d. Quan hệ biện chứng giữa tồn tại xã hội và ý thức xã hội)","c":5,"v":"khớp","id":"dv-IV.6","p":4,"t":"Trắc nghiệm"},
{"q":"Tư tưởng \"trọng nam khinh nữ\" vẫn còn tồn tại trong xã hội hiện nay là biểu hiện của:","o":["Ý thức xã hội lạc hậu so với tồn tại xã hội","Ý thức xã hội vượt trước tồn tại xã hội","Tồn tại xã hội phụ thuộc vào ý thức xã hội","Sự tác động qua lại giữa các hình thái ý thức"],"a":[0],"e":"Điều kiện kinh tế – xã hội đã thay đổi nhưng quan niệm «trọng nam khinh nữ» vẫn còn, do sức ỳ của thói quen, truyền thống, tập quán và do lợi ích của một số nhóm người — biểu hiện ý thức xã hội thường lạc hậu so với tồn tại xã hội.","w":["","Vượt trước là tư tưởng khoa học dự báo được tương lai, không phải tàn dư cũ.","Đảo ngược quan hệ: tồn tại xã hội quyết định ý thức.","Tác động qua lại giữa các hình thái không phải nội dung chính của hiện tượng này."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (d)","c":5,"v":"khớp","id":"dv-IV.7","p":4,"t":"Trắc nghiệm"},
{"q":"\"Giai cấp nào chi phối những tư liệu sản xuất vật chất thì cũng chi phối luôn cả những tư liệu sản xuất tinh thần.\" Luận điểm này nói về:","o":["Tính kế thừa của ý thức xã hội","Tính giai cấp của ý thức xã hội","Tính lạc hậu của ý thức xã hội","Tính vượt trước của ý thức xã hội"],"a":[1],"e":"Luận điểm của C. Mác và Ph. Ăngghen trong «Hệ tư tưởng Đức»: giai cấp chi phối tư liệu sản xuất vật chất thì cũng chi phối tư liệu sản xuất tinh thần, nên tư tưởng thống trị là tư tưởng của giai cấp thống trị — tính giai cấp của ý thức xã hội.","w":["Tính kế thừa là tiếp nhận giá trị tinh thần của thế hệ trước.","","Tính lạc hậu là chậm biến đổi so với tồn tại xã hội.","Tính vượt trước là phản ánh trước xu hướng tương lai."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (c. Tính giai cấp của ý thức xã hội); C. Mác – Ph. Ăngghen, «Hệ tư tưởng Đức»","c":5,"v":"khớp","id":"dv-IV.8","p":4,"t":"Trắc nghiệm"},
{"q":"Hình thái ý thức xã hội phản ánh trực tiếp và tập trung các quan hệ kinh tế giữa các giai cấp là:","o":["Ý thức nghệ thuật","Ý thức tôn giáo","Ý thức đạo đức","Ý thức chính trị"],"a":[3],"e":"Ý thức chính trị phản ánh trực tiếp các quan hệ kinh tế dưới dạng lợi ích giai cấp và quan hệ quyền lực nhà nước. Giáo trình dẫn Lênin: «Chính trị là sự biểu hiện tập trung của kinh tế». Ý thức chính trị gần gũi với cơ sở kinh tế nhất (cùng ý thức pháp quyền).","w":["Ý thức nghệ thuật phản ánh hiện thực bằng hình tượng, gián tiếp với kinh tế.","Ý thức tôn giáo phản ánh hư ảo, xa cơ sở kinh tế.","Ý thức đạo đức điều chỉnh hành vi bằng dư luận, lương tâm, không phản ánh tập trung quan hệ kinh tế giữa các giai cấp.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (e. Các hình thái ý thức xã hội); Ch.3, mục I.3 (Biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng)","c":5,"v":"khớp","id":"dv-IV.9","p":4,"t":"Trắc nghiệm"},
{"q":"Ví dụ nào thể hiện ý thức xã hội VƯỢT TRƯỚC tồn tại xã hội?","o":["Phong tục cưới hỏi linh đình vẫn còn phổ biến","Tâm lý tiểu nông trong sản xuất công nghiệp","Dự báo khoa học về xu hướng xã hội tương lai","Thói quen mê tín dị đoan trong đời sống"],"a":[2],"e":"Tư tưởng khoa học tiên tiến có thể phản ánh đúng quy luật và dự báo xu hướng tương lai — ý thức xã hội vượt trước tồn tại xã hội. Ba phương án còn lại đều là tàn dư cũ, biểu hiện của ý thức lạc hậu.","w":["Hủ tục cưới hỏi là ý thức lạc hậu.","Tâm lý tiểu nông trong sản xuất công nghiệp là ý thức lạc hậu.","","Mê tín dị đoan là ý thức lạc hậu."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (d)","c":5,"v":"khớp","id":"dv-IV.10","p":4,"t":"Trắc nghiệm"},
{"q":"Ý thức xã hội chỉ là sự phản ánh thụ động, không có tác động gì đến tồn tại xã hội.","o":["Đúng","Sai"],"a":[1],"e":"Sai. Ý thức xã hội có tính độc lập tương đối và tác động trở lại tồn tại xã hội (thúc đẩy hoặc kìm hãm), thông qua hoạt động thực tiễn của con người.","w":["Quan điểm duy vật tầm thường, phủ nhận vai trò tích cực của ý thức.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (d)","c":5,"v":"khớp","id":"dv-IV.11","p":4,"t":"Đúng/Sai","f":1},
{"q":"Trong xã hội có giai cấp, ý thức xã hội mang tính giai cấp.","o":["Đúng","Sai"],"a":[0],"e":"Đúng. Giáo trình: trong xã hội có giai cấp, các giai cấp có điều kiện vật chất, lợi ích, địa vị khác nhau nên ý thức xã hội của họ khác nhau; tính giai cấp biểu hiện cả ở tâm lý xã hội lẫn hệ tư tưởng.","w":["","Phủ nhận tính giai cấp của ý thức xã hội."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (c. Tính giai cấp của ý thức xã hội)","c":5,"v":"khớp","id":"dv-IV.12","p":4,"t":"Đúng/Sai","f":1},
{"q":"Ý thức khoa học là một hình thái ý thức xã hội.","o":["Đúng","Sai"],"a":[0],"e":"Đúng. Giáo trình liệt kê các hình thái chủ yếu: ý thức chính trị, pháp quyền, đạo đức, ý thức lý luận (hay ý thức khoa học), thẩm mỹ (nghệ thuật), tôn giáo; ngoài ra còn ý thức triết học.","w":["","Ý thức khoa học là một hình thái ý thức xã hội theo giáo trình."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (e. Các hình thái ý thức xã hội)","c":5,"v":"khớp","id":"dv-IV.13","p":4,"t":"Đúng/Sai","f":1},
{"q":"Khi tồn tại xã hội cũ mất đi, mọi quan niệm cũ cũng lập tức biến mất theo.","o":["Đúng","Sai"],"a":[1],"e":"Sai. Ý thức xã hội thường lạc hậu so với tồn tại xã hội: nhiều quan niệm cũ còn tồn tại lâu do sức ỳ của thói quen, truyền thống, tập quán và do lợi ích của một số nhóm người.","w":["«Lập tức» là dấu hiệu tuyệt đối hóa — nhận định sai thường gặp.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (d)","c":5,"v":"khớp","id":"dv-IV.14","p":4,"t":"Đúng/Sai","f":1},
{"q":"Một tin giả về khan hiếm hàng hóa lan nhanh trên mạng xã hội khiến nhiều người đổ xô mua tích trữ. Hiện tượng hoảng loạn tập thể này thuộc về:","o":["Tâm lý xã hội","Hệ tư tưởng","Ý thức lý luận","Ý thức khoa học"],"a":[0],"e":"Tâm lý xã hội gồm tình cảm, tâm trạng, thói quen… hình thành tự phát dưới tác động trực tiếp của đời sống hằng ngày, chỉ ghi lại cái bề mặt. Hoảng loạn đám đông vì tin giả là ví dụ điển hình.","w":["","Hệ tư tưởng là nhận thức lý luận, tự giác, có hệ thống.","Ý thức lý luận là tri thức đã được hệ thống hóa thành học thuyết.","Ý thức khoa học phản ánh bản chất, quy luật — trái ngược với phản ứng hoảng loạn."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (b. Kết cấu của ý thức xã hội)","c":5,"v":"khớp","id":"dv-IV.15","p":4,"t":"Trắc nghiệm"},
{"q":"Nhận thức về biến đổi khí hậu thúc đẩy nhiều quốc gia ban hành chính sách giảm phát thải, làm thay đổi cách sản xuất. Điều này minh họa:","o":["Ý thức xã hội tác động trở lại tồn tại xã hội","Tồn tại xã hội không phụ thuộc vào con người","Ý thức xã hội luôn lạc hậu so với tồn tại xã hội","Tồn tại xã hội và ý thức xã hội tách rời nhau"],"a":[0],"e":"Nhận thức về biến đổi khí hậu (ý thức xã hội, tri thức khoa học) thông qua chính sách và hoạt động thực tiễn đã làm thay đổi cách sản xuất (tồn tại xã hội) — ý thức xã hội tác động trở lại tồn tại xã hội.","w":["","Tồn tại xã hội là sinh hoạt vật chất của con người, chịu tác động của con người.","Ở đây ý thức đi trước, dẫn dắt thay đổi — không phải lạc hậu.","Hai mặt gắn bó biện chứng, không tách rời."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (d)","c":5,"v":"khớp","id":"dv-IV.16","p":4,"t":"Trắc nghiệm"},
{"q":"Ghép hình thái ý thức xã hội với đặc trưng của nó:\n1. Ý thức pháp quyền · 2. Ý thức đạo đức · 3. Ý thức thẩm mỹ\na. Điều chỉnh hành vi bằng pháp luật, có cưỡng chế\nb. Phản ánh hiện thực bằng hình tượng nghệ thuật\nc. Điều chỉnh hành vi bằng dư luận và lương tâm","o":["1-a, 2-c, 3-b","1-c, 2-a, 3-b","1-a, 2-b, 3-c","1-b, 2-c, 3-a"],"a":[0],"e":"Ý thức pháp quyền gắn với pháp luật và sự cưỡng chế của nhà nước (1-a). Ý thức đạo đức điều chỉnh hành vi bằng dư luận xã hội và lương tâm (2-c). Ý thức thẩm mỹ phản ánh hiện thực bằng hình tượng nghệ thuật (3-b).","w":["","Đạo đức không dựa vào cưỡng chế pháp luật; pháp quyền không dựa vào lương tâm.","Đạo đức không phản ánh bằng hình tượng nghệ thuật; thẩm mỹ không điều chỉnh bằng dư luận, lương tâm.","Pháp quyền không phản ánh bằng hình tượng; thẩm mỹ không dùng cưỡng chế pháp luật."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (e. Các hình thái ý thức xã hội)","c":5,"v":"khớp","id":"dv-IV.17","p":4,"t":"Ghép đôi"},
{"q":"Tinh thần yêu nước, \"uống nước nhớ nguồn\" được truyền qua nhiều thế hệ người Việt là biểu hiện của:","o":["Tính kế thừa của ý thức xã hội","Tính vượt trước của ý thức xã hội","Sự quyết định của ý thức đối với tồn tại","Tính giai cấp của ý thức xã hội"],"a":[0],"e":"Ý thức xã hội có tính kế thừa: các giá trị tinh thần của thế hệ trước (yêu nước, uống nước nhớ nguồn) được thế hệ sau tiếp nhận và phát triển trong điều kiện mới.","w":["","Vượt trước là dự báo tương lai, không phải truyền thống được lưu giữ.","Ý thức không quyết định tồn tại.","Đây là giá trị chung của dân tộc, không nhằm thể hiện tính giai cấp."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (d)","c":5,"v":"khớp","id":"dv-IV.18","p":4,"t":"Trắc nghiệm"},
{"q":"Theo chủ nghĩa duy vật lịch sử, nguồn gốc sâu xa của các quan điểm, tư tưởng trong xã hội là:","o":["Tồn tại xã hội, trước hết là kinh tế","Tư duy thiên tài của các nhà tư tưởng lớn","Ý muốn chủ quan của giai cấp cầm quyền","Sự mặc khải của các lực lượng siêu nhiên"],"a":[0],"e":"Tồn tại xã hội quyết định ý thức xã hội. Muốn hiểu một tư tưởng phải tìm nguồn gốc của nó trong điều kiện sinh hoạt vật chất, trước hết là phương thức sản xuất (kinh tế).","w":["","Coi thiên tài là nguồn gốc tư tưởng là quan điểm duy tâm.","Ý muốn chủ quan của giai cấp cầm quyền cũng bắt nguồn từ lợi ích kinh tế.","Mặc khải siêu nhiên là quan điểm tôn giáo, duy tâm."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (d)","c":5,"v":"khớp","id":"dv-IV.19","p":4,"t":"Trắc nghiệm"},
{"q":"\"Mình chỉ cần quyết tâm thật cao là được điểm A, không cần ôn bài.\" Suy nghĩ này là một biểu hiện đời thường của:","o":["Bệnh chủ quan duy ý chí","Tôn trọng quy luật khách quan","Phát huy tính năng động chủ quan","Tính kế thừa của ý thức"],"a":[0],"e":"Ý chí, quyết tâm là cần, nhưng tuyệt đối hóa chúng, bất chấp điều kiện khách quan (phải ôn bài) là bệnh chủ quan duy ý chí. Giáo trình: phải xuất phát từ thực tế khách quan, tránh chủ nghĩa chủ quan, bệnh chủ quan duy ý chí, đồng thời phát huy tính năng động sáng tạo của ý thức.","w":["","Ngược lại: suy nghĩ này coi thường điều kiện khách quan.","Phát huy tính năng động chủ quan đúng đắn phải dựa trên tôn trọng quy luật khách quan; ở đây là tuyệt đối hóa ý chí.","Không liên quan tới tính kế thừa."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.2, mục I (ý nghĩa phương pháp luận của quan hệ vật chất – ý thức)","c":5,"v":"khớp","id":"dv-IV.20","p":4,"t":"Trắc nghiệm"},
{"q":"\"Chỉ cần tuyên truyền thật nhiều là mọi hủ tục sẽ biến mất ngay.\" Lập luận này sai vì:","o":["Bỏ qua tính lạc hậu và sức ỳ của ý thức xã hội","Đánh giá đúng mức vai trò của công tác tuyên truyền","Cho rằng ý thức xã hội có tính kế thừa","Thừa nhận tồn tại xã hội quyết định ý thức"],"a":[0],"e":"Hủ tục là ý thức lạc hậu có sức ỳ lớn. Muốn thay đổi phải thay đổi điều kiện sống (tồn tại xã hội) kết hợp với giáo dục, và cần thời gian. Tin rằng chỉ tuyên truyền là hủ tục biến mất «ngay» là duy ý chí.","w":["","Lập luận đánh giá quá cao, không đúng mức, vai trò tuyên truyền.","Lập luận không nói tới tính kế thừa.","Lập luận bỏ qua, chứ không thừa nhận, vai trò quyết định của tồn tại xã hội."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (d)","c":5,"v":"khớp","id":"dv-IV.21","p":4,"t":"Tìm lỗi lập luận"},
{"q":"\"Ý thức con người chỉ là bản sao máy móc của hoàn cảnh, nên con người không phải chịu trách nhiệm về suy nghĩ của mình.\" Nhận định này sai vì:","o":["Phủ nhận tính độc lập tương đối của ý thức","Thừa nhận tồn tại xã hội quyết định ý thức xã hội","Đề cao vai trò của hoàn cảnh sống","Cho rằng ý thức có nguồn gốc xã hội"],"a":[0],"e":"Tồn tại xã hội quyết định ý thức, nhưng ý thức có tính năng động, độc lập tương đối và tác động trở lại; con người vẫn có khả năng lựa chọn, sáng tạo và chịu trách nhiệm. Coi ý thức là «bản sao máy móc» là duy vật tầm thường.","w":["","Thừa nhận tồn tại xã hội quyết định là đúng; cái sai là tuyệt đối hóa thành phản ánh máy móc.","Đề cao hoàn cảnh không sai; sai ở chỗ phủ nhận vai trò chủ động của ý thức.","Ý thức có nguồn gốc xã hội là đúng."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (d)","c":5,"v":"khớp","id":"dv-IV.22","p":4,"t":"Tìm lỗi lập luận"},
{"q":"Một người nhận xét: \"Thế hệ trẻ bây giờ toàn sống ảo, mất hết truyền thống.\" Lỗi chủ yếu của nhận xét này là:","o":["Vơ đũa cả nắm, nhìn phiến diện một chiều","Đánh giá đúng xu hướng của ý thức xã hội","Thể hiện tính kế thừa của ý thức xã hội","Phản ánh tính vượt trước của ý thức xã hội"],"a":[0],"e":"Khái quát vội vàng từ một số hiện tượng thành «toàn bộ thế hệ trẻ» là vi phạm quan điểm toàn diện. Cần thấy cả mặt tích cực, tính kế thừa và giá trị mới mà thế hệ trẻ tạo ra.","w":["","Nhận xét phiến diện, không phản ánh đúng xu hướng.","Nhận xét phủ nhận, chứ không thể hiện, tính kế thừa.","Không liên quan tới tính vượt trước."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.2, mục II (quan điểm toàn diện); Ch.3, mục IV.2 (d)","c":5,"v":"khớp","id":"dv-IV.23","p":4,"t":"Tìm lỗi lập luận"},
{"q":"Trào lưu \"quiet quitting\" (chỉ làm việc vừa đủ, không cống hiến thêm) lan rộng trong giới trẻ trên mạng xã hội. Ở cấp độ ý thức xã hội, trào lưu này trước hết thuộc về:","o":["Tâm lý xã hội","Hệ tư tưởng chính thống","Ý thức pháp quyền","Ý thức khoa học"],"a":[0],"e":"«Quiet quitting» là tâm trạng, thái độ hình thành tự phát, phản ánh trực tiếp điều kiện lao động và áp lực công việc hằng ngày — đặc trưng của tâm lý xã hội.","w":["","Hệ tư tưởng chính thống là hệ thống lý luận tự giác của giai cấp cầm quyền.","Ý thức pháp quyền gắn với pháp luật, quyền và nghĩa vụ pháp lý.","Ý thức khoa học phản ánh bản chất, quy luật bằng hệ thống khái niệm."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (b. Kết cấu của ý thức xã hội)","c":5,"v":"khớp","id":"dv-IV.24","p":4,"t":"Tình huống thời sự"},
{"q":"Nhiều người tin vào các \"thầy\" bói toán trên mạng để chọn ngày đi thi, đi phỏng vấn. Theo chủ nghĩa duy vật lịch sử, cách giải thích đúng về hiện tượng này là:","o":["Ý thức xã hội có thể lạc hậu so với đời sống","Điều kiện vật chất không ảnh hưởng tới niềm tin","Đây là bằng chứng ý thức quyết định tồn tại","Niềm tin này phản ánh đúng quy luật khách quan"],"a":[0],"e":"Dù khoa học phát triển, những quan niệm cũ vẫn tồn tại do sức ỳ của tâm lý, thói quen và tâm lý cầu may khi bất an — biểu hiện ý thức xã hội có thể lạc hậu so với đời sống (tồn tại xã hội).","w":["","Điều kiện vật chất (bất an về việc làm, thi cử) ảnh hưởng mạnh tới niềm tin.","Đây không phải bằng chứng ý thức quyết định tồn tại.","Bói toán không phản ánh quy luật khách quan."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (d)","c":5,"v":"khớp","id":"dv-IV.25","p":4,"t":"Tình huống thời sự"},
{"q":"Mạng xã hội dùng thuật toán đề xuất nội dung theo sở thích, khiến mỗi người chủ yếu thấy quan điểm giống mình. Hệ quả dễ thấy đối với nhận thức là:","o":["Dễ hình thành cách nhìn phiến diện, một chiều","Nhận thức tự động trở nên toàn diện và khách quan hơn","Tồn tại xã hội không còn quyết định ý thức","Ý thức xã hội mất hẳn tính giai cấp"],"a":[0],"e":"Môi trường tiếp nhận thông tin là một phần điều kiện sống và định hình ý thức. «Bong bóng lọc» của thuật toán khiến con người dễ có cách nhìn phiến diện; muốn nhìn toàn diện phải chủ động tiếp cận thông tin đa chiều.","w":["","Ngược lại: thuật toán thu hẹp, không mở rộng góc nhìn.","Thuật toán cũng là một phần điều kiện sống; tồn tại xã hội vẫn quyết định ý thức.","Hiện tượng này không làm mất tính giai cấp của ý thức xã hội."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (d); Ch.2, mục II (quan điểm toàn diện)","c":5,"v":"khớp","id":"dv-IV.26","p":4,"t":"Tình huống thời sự"},
{"q":"Phong trào quyên góp cứu trợ đồng bào vùng lũ lan tỏa nhanh trên mạng xã hội. Đây là biểu hiện của:","o":["Truyền thống tương thân tương ái được kế thừa","Ý thức xã hội tách rời hoàn toàn khỏi tồn tại xã hội","Hệ tư tưởng của giai cấp bóc lột trong xã hội cũ","Sự tiêu vong của ý thức đạo đức"],"a":[0],"e":"Truyền thống «lá lành đùm lá rách», tương thân tương ái được thế hệ hôm nay tiếp nối bằng phương tiện mới (mạng xã hội) — biểu hiện tính kế thừa của ý thức xã hội.","w":["","Phong trào xuất phát từ hoàn cảnh thực tế (lũ lụt), không tách rời tồn tại xã hội.","Đây là giá trị đạo đức tốt đẹp của dân tộc, không phải hệ tư tưởng bóc lột.","Ngược lại: ý thức đạo đức được phát huy."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục IV.2 (d)","c":5,"v":"khớp","id":"dv-IV.27","p":4,"t":"Tình huống thời sự"},
{"q":"\"Trong tính hiện thực của nó, bản chất con người là tổng hòa những quan hệ xã hội.\" Luận điểm này được C. Mác nêu trong:","o":["Luận cương về Phoiơbắc","Tuyên ngôn của Đảng Cộng sản","Bộ Tư bản, quyển I","Biện chứng của tự nhiên"],"a":[0],"e":"Luận cương thứ sáu trong «Luận cương về Phoiơbắc» (1845): «Trong tính hiện thực của nó, bản chất con người là tổng hòa những quan hệ xã hội». Mác phê phán Phoiơbắc hiểu con người trừu tượng.","w":["","Tuyên ngôn (1848) nêu mục tiêu giải phóng con người, không chứa luận điểm này.","«Tư bản» phân tích phương thức sản xuất tư bản chủ nghĩa.","«Biện chứng của tự nhiên» là tác phẩm của Ăngghen về khoa học tự nhiên."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.1 (Khái niệm con người và bản chất con người); C. Mác, «Luận cương về Phoiơbắc» (1845)","c":5,"v":"khớp","id":"dv-V.1","p":5,"t":"Trắc nghiệm"},
{"q":"Theo quan điểm mácxít, con người là thực thể thống nhất giữa:","o":["Phần linh hồn và phần thể xác","Đời sống lý trí và đời sống cảm xúc","Mặt sinh vật và mặt xã hội","Cá nhân và cộng đồng"],"a":[2],"e":"Con người là thực thể thống nhất giữa mặt sinh vật (tự nhiên) và mặt xã hội. Mặt sinh vật là tiền đề; mặt xã hội quy định bản chất con người.","w":["Linh hồn – thể xác là cách chia của tôn giáo, duy tâm.","Lý trí – cảm xúc là các mặt của đời sống tâm lý, không phải định nghĩa con người.","","Cá nhân – cộng đồng là quan hệ giữa con người với xã hội, không phải hai mặt cấu thành con người."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.1 (Khái niệm con người và bản chất con người)","c":5,"v":"khớp","id":"dv-V.2","p":5,"t":"Trắc nghiệm"},
{"q":"Hạn chế của L. Phoiơbắc trong quan niệm về con người là:","o":["Coi con người là sản phẩm của thượng đế","Hiểu con người trừu tượng, tách khỏi xã hội","Phủ nhận hoàn toàn mặt sinh học của con người","Đồng nhất con người với ý niệm tuyệt đối"],"a":[1],"e":"Giáo trình: chủ nghĩa duy vật Phoiơbắc là quan điểm nhân bản, xem xét con người «tộc loại, phi lịch sử, phi giai cấp». Ông không thấy con người trong hoạt động thực tiễn và các quan hệ xã hội.","w":["Phoiơbắc là nhà duy vật, phê phán tôn giáo; ông không coi con người do thượng đế tạo ra.","","Ngược lại, Phoiơbắc tuyệt đối hóa mặt sinh học.","Đồng nhất con người với ý niệm tuyệt đối là quan điểm của Hêghen."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.1 (Khái niệm con người và bản chất con người); Ch.1, mục II (tiền đề lý luận – triết học Phoiơbắc)","c":5,"v":"khớp","id":"dv-V.3","p":5,"t":"Trắc nghiệm"},
{"q":"Theo C. Mác, nguồn gốc của hiện tượng tha hóa con người là:","o":["Bản năng tự nhiên vốn có của con người","Sự phát triển của khoa học kỹ thuật","Trình độ hiểu biết thấp của người lao động","Chế độ tư hữu và người bóc lột người"],"a":[3],"e":"Trong «Bản thảo kinh tế - triết học năm 1844», Mác chỉ ra nguồn gốc của tha hóa là chế độ tư hữu và tình trạng người bóc lột người. Giáo trình: tha hóa là hiện tượng lịch sử đặc thù, chỉ có trong xã hội có giai cấp và tư hữu về tư liệu sản xuất.","w":["Tha hóa không phải bản năng tự nhiên; nó có nguồn gốc xã hội.","Khoa học kỹ thuật tự nó không sinh ra tha hóa.","Trình độ hiểu biết không phải nguồn gốc tha hóa.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.2 (Hiện tượng tha hóa con người và vấn đề giải phóng con người)","c":5,"v":"khớp","id":"dv-V.4","p":5,"t":"Trắc nghiệm"},
{"q":"Thực chất của hiện tượng tha hóa con người là:","o":["Lao động của con người bị tha hóa","Con người tách khỏi giới tự nhiên","Ý thức của con người bị lệch lạc","Nhu cầu tiêu dùng bị kích thích quá mức"],"a":[0],"e":"Giáo trình (mục V.2) ghi nguyên văn: «Thực chất của hiện tượng tha hóa con người là lao động của con người bị tha hóa» — quá trình lao động và sản phẩm lao động từ chỗ phục vụ, phát triển con người bị biến thành lực lượng đối lập, nô dịch và thống trị con người.","w":["","Không phải tách khỏi tự nhiên; tha hóa diễn ra trong quan hệ xã hội.","Lệch lạc ý thức là biểu hiện, không phải thực chất.","Kích thích tiêu dùng có thể là biểu hiện hiện đại, không phải thực chất."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.2 (Hiện tượng tha hóa con người và vấn đề giải phóng con người)","c":5,"v":"khớp","id":"dv-V.5","p":5,"t":"Trắc nghiệm"},
{"q":"\"Sự phát triển tự do của mỗi người là điều kiện cho sự phát triển tự do của tất cả mọi người.\" Đây là mục tiêu được nêu trong:","o":["Hệ tư tưởng Đức","Bản thảo kinh tế - triết học 1844","Tuyên ngôn của Đảng Cộng sản","Nhà nước và cách mạng"],"a":[2],"e":"«Tuyên ngôn của Đảng Cộng sản» (1848) kết luận: thay cho xã hội tư sản cũ sẽ là một liên hợp, trong đó «sự phát triển tự do của mỗi người là điều kiện cho sự phát triển tự do của tất cả mọi người» — mục tiêu giải phóng con người.","w":["«Hệ tư tưởng Đức» (1845–1846) trình bày quan niệm duy vật về lịch sử.","«Bản thảo 1844» phân tích lao động bị tha hóa.","","«Nhà nước và cách mạng» là tác phẩm của Lênin (1917)."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.2 (Hiện tượng tha hóa con người và vấn đề giải phóng con người); C. Mác – Ph. Ăngghen, «Tuyên ngôn của Đảng Cộng sản» (1848)","c":5,"v":"khớp","id":"dv-V.6","p":5,"t":"Trắc nghiệm"},
{"q":"Theo chủ nghĩa duy vật lịch sử, chủ thể sáng tạo chân chính ra lịch sử là:","o":["Các vĩ nhân, anh hùng","Quần chúng nhân dân","Tầng lớp trí thức tinh hoa","Giai cấp thống trị"],"a":[1],"e":"Giáo trình: quần chúng nhân dân là chủ thể sáng tạo chân chính, là động lực phát triển của lịch sử — lực lượng sản xuất cơ bản, động lực của các cuộc cách mạng và người sáng tạo giá trị văn hóa tinh thần.","w":["Coi vĩ nhân là chủ thể sáng tạo lịch sử là quan điểm duy tâm.","","Trí thức là bộ phận của quần chúng, không thay thế quần chúng.","Giai cấp thống trị (bóc lột) không phải chủ thể sáng tạo chân chính."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.3 (b. Vai trò của quần chúng nhân dân và lãnh tụ)","c":5,"v":"khớp","id":"dv-V.7","p":5,"t":"Trắc nghiệm"},
{"q":"Quan điểm \"anh hùng tạo thời thế\", cho rằng lịch sử do các vĩ nhân quyết định, thuộc lập trường:","o":["Duy vật lịch sử","Duy vật biện chứng","Chủ nghĩa xã hội khoa học","Duy tâm về lịch sử"],"a":[3],"e":"Tuyệt đối hóa vai trò cá nhân kiệt xuất («anh hùng tạo thời thế») là quan điểm duy tâm về lịch sử. Duy vật lịch sử: lãnh tụ quan trọng nhưng là sản phẩm của thời đại, không quyết định tiến trình lịch sử.","w":["Duy vật lịch sử khẳng định quần chúng mới là chủ thể sáng tạo lịch sử.","Duy vật biện chứng không coi ý chí cá nhân quyết định.","Chủ nghĩa xã hội khoa học đề cao vai trò quần chúng, giai cấp công nhân.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.3 (b)","c":5,"v":"khớp","id":"dv-V.8","p":5,"t":"Trắc nghiệm"},
{"q":"Về sự xuất hiện của lãnh tụ, quan điểm đúng là:","o":["Tất yếu, nhưng ai làm lãnh tụ là ngẫu nhiên","Hoàn toàn ngẫu nhiên, không theo quy luật nào","Do tài năng bẩm sinh quyết định tất cả","Tất yếu cả về thời điểm lẫn con người cụ thể"],"a":[0],"e":"Giáo trình: «Lãnh tụ là sản phẩm của thời đại, của cộng đồng, của phong trào» — khi lịch sử đặt ra nhiệm vụ thì phong trào sẽ sản sinh ra người đáp ứng. Ăngghen (thư gửi W. Borgius, 1894): sự xuất hiện của «vĩ nhân» là tất yếu, còn chính người đó xuất hiện ở đúng lúc ấy là ngẫu nhiên; không có người này thì sẽ có người khác thay thế.","w":["","Phủ nhận tính tất yếu, quy luật của sự xuất hiện lãnh tụ.","Tài năng cá nhân là cần nhưng không quyết định tất cả; lãnh tụ phải gắn với phong trào.","Tuyệt đối hóa tính tất yếu, rơi vào thuyết định mệnh."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.3 (b); Ph. Ăngghen, Thư gửi W. Borgius (1894)","c":5,"v":"khớp","id":"dv-V.9","p":5,"t":"Trắc nghiệm"},
{"q":"Quan điểm của Đảng Cộng sản Việt Nam về vai trò con người trong sự nghiệp đổi mới là:","o":["Con người là phương tiện của tăng trưởng","Con người là sản phẩm thụ động của hoàn cảnh","Con người vừa là mục tiêu, vừa là động lực","Kinh tế là trung tâm, con người là thứ yếu"],"a":[2],"e":"Đảng xác định phát huy nhân tố con người: con người là trung tâm của chiến lược phát triển, vừa là mục tiêu vừa là động lực. Giáo trình nêu đây là một nội dung cơ bản trong tư tưởng Hồ Chí Minh về con người («con người vừa là mục tiêu, vừa là động lực của cách mạng»).","w":["Coi con người chỉ là phương tiện là quan điểm thực dụng, trái đường lối.","Con người là chủ thể năng động, không thụ động.","","Đảng đặt con người ở vị trí trung tâm."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.4 (vấn đề con người trong sự nghiệp cách mạng ở Việt Nam)","c":5,"v":"khớp","id":"dv-V.10","p":5,"t":"Trắc nghiệm"},
{"q":"Theo C. Mác, con người chỉ là một thực thể sinh học như mọi loài động vật.","o":["Đúng","Sai"],"a":[1],"e":"Sai. Con người là thực thể sinh học – xã hội. Khác động vật ở chỗ biết lao động, chế tạo và sử dụng công cụ; mặt xã hội quy định bản chất con người.","w":["Quan điểm sinh học hóa con người (gần với hạn chế của Phoiơbắc).",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.1 (Khái niệm con người và bản chất con người)","c":5,"v":"khớp","id":"dv-V.11","p":5,"t":"Đúng/Sai","f":1},
{"q":"Lãnh tụ có thể thay đổi tiến trình khách quan của lịch sử theo ý muốn riêng.","o":["Đúng","Sai"],"a":[1],"e":"Sai. Lãnh tụ có thể thúc đẩy hoặc kìm hãm tiến trình lịch sử, nhưng không thể thay đổi xu hướng khách quan của nó. Con người sáng tạo lịch sử trong những điều kiện khách quan do lịch sử để lại.","w":["Tuyệt đối hóa vai trò cá nhân — quan điểm duy tâm.",""],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.3 (b)","c":5,"v":"khớp","id":"dv-V.12","p":5,"t":"Đúng/Sai","f":1},
{"q":"Theo C. Mác, giải phóng con người gắn liền với xóa bỏ chế độ người bóc lột người.","o":["Đúng","Sai"],"a":[0],"e":"Đúng. Theo Mác, muốn khắc phục tha hóa và giải phóng con người phải xóa bỏ chế độ tư hữu và tình trạng người bóc lột người; giải phóng con người gắn với giải phóng giai cấp, giải phóng xã hội.","w":["","Tách giải phóng con người khỏi điều kiện kinh tế – xã hội của nó."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.2 (Hiện tượng tha hóa con người và vấn đề giải phóng con người)","c":5,"v":"khớp","id":"dv-V.13","p":5,"t":"Đúng/Sai","f":1},
{"q":"Sắp xếp các tác phẩm sau theo thời gian ra đời, từ sớm nhất:\n(1) Luận cương về Phoiơbắc · (2) Bản thảo kinh tế - triết học · (3) Tư bản, quyển I · (4) Tuyên ngôn của Đảng Cộng sản","o":["2 → 1 → 4 → 3","1 → 2 → 4 → 3","2 → 4 → 1 → 3","2 → 1 → 3 → 4"],"a":[0],"e":"Bản thảo kinh tế - triết học (1844) → Luận cương về Phoiơbắc (1845) → Tuyên ngôn của Đảng Cộng sản (1848) → Tư bản, quyển I (1867).","w":["","Luận cương về Phoiơbắc (1845) ra đời sau Bản thảo (1844).","Tuyên ngôn (1848) ra đời sau Luận cương (1845).","Tư bản quyển I (1867) ra đời sau Tuyên ngôn (1848)."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.1, mục II (sự hình thành triết học Mác)","c":5,"v":"khớp","id":"dv-V.14","p":5,"t":"Sắp xếp"},
{"q":"Một sinh viên chạy giao hàng 12 giờ mỗi ngày, thu nhập do thuật toán quyết định, cảm thấy công việc xa lạ và không còn thời gian phát triển bản thân. Theo C. Mác, trải nghiệm này gần với:","o":["Sự tha hóa trong lao động","Sự phát triển tự do toàn diện","Bản chất sinh học của con người","Vai trò quyết định của lãnh tụ"],"a":[0],"e":"Lao động kéo dài, thu nhập do thuật toán quyết định, công việc trở nên xa lạ và không còn thời gian phát triển bản thân: quá trình lao động trở thành lực lượng đối lập, chi phối người lao động — gần với hiện tượng lao động bị tha hóa mà Mác phân tích.","w":["","Ngược lại: người lao động không có điều kiện phát triển tự do.","Đây là vấn đề quan hệ xã hội, không phải bản chất sinh học.","Không liên quan tới vai trò lãnh tụ."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.2 (Hiện tượng tha hóa con người và vấn đề giải phóng con người)","c":5,"v":"khớp","id":"dv-V.15","p":5,"t":"Trắc nghiệm"},
{"q":"Để hiểu đúng một con người cụ thể theo quan điểm mácxít, cần xem xét trước hết:","o":["Các quan hệ xã hội mà người đó tham gia","Đặc điểm sinh học, di truyền bẩm sinh","Ngày sinh và cung hoàng đạo của người đó","Ý chí, mong muốn chủ quan của người đó"],"a":[0],"e":"Bản chất con người là tổng hòa các quan hệ xã hội; muốn hiểu một con người cụ thể phải xem xét các quan hệ xã hội mà người đó tham gia (gia đình, nghề nghiệp, giai cấp, dân tộc…) và hoạt động thực tiễn của họ — quan điểm toàn diện, lịch sử – cụ thể.","w":["","Mặt sinh học là tiền đề nhưng không quy định bản chất.","Chiêm tinh là mê tín, không có cơ sở khoa học.","Ý chí chủ quan cũng hình thành từ các quan hệ xã hội; dựa vào nó là phiến diện."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.1 (Khái niệm con người và bản chất con người)","c":5,"v":"khớp","id":"dv-V.16","p":5,"t":"Trắc nghiệm"},
{"q":"Ghép nhà tư tưởng với quan niệm về con người:\n1. L. Phoiơbắc · 2. G.W.F. Hêghen · 3. C. Mác\na. Con người là tổng hòa các quan hệ xã hội\nb. Con người là hiện thân của ý niệm tuyệt đối\nc. Con người trừu tượng, thiên về mặt sinh học","o":["1-c, 2-b, 3-a","1-a, 2-b, 3-c","1-b, 2-c, 3-a","1-c, 2-a, 3-b"],"a":[0],"e":"Phoiơbắc hiểu con người trừu tượng, thiên về mặt sinh học (1-c). Hêghen (duy tâm khách quan) coi con người là hiện thân, là sự tự ý thức của «ý niệm tuyệt đối» (2-b). Mác: bản chất con người là tổng hòa các quan hệ xã hội (3-a).","w":["","Gán quan niệm của Mác cho Phoiơbắc và của Phoiơbắc cho Mác.","Phoiơbắc là nhà duy vật, không gắn con người với ý niệm tuyệt đối.","Hêghen không có quan niệm «tổng hòa các quan hệ xã hội»."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.1 (Khái niệm con người và bản chất con người); Ch.2, mục I.2 (quan niệm duy tâm về ý thức)","c":5,"v":"khớp","id":"dv-V.17","p":5,"t":"Ghép đôi"},
{"q":"Theo quan điểm của Đảng, nguồn lực quan trọng nhất cho sự phát triển nhanh và bền vững của đất nước là:","o":["Nguồn lực con người","Tài nguyên thiên nhiên","Vốn đầu tư nước ngoài","Vị trí địa lý thuận lợi"],"a":[0],"e":"Đảng xác định con người là trung tâm, là chủ thể và nguồn lực quan trọng nhất của sự phát triển; lấy việc phát huy nguồn lực con người làm yếu tố cơ bản cho sự phát triển nhanh và bền vững.","w":["","Tài nguyên thiên nhiên có hạn và chỉ phát huy qua lao động của con người.","Vốn nước ngoài là nguồn lực bổ sung, quan trọng nhưng không phải quan trọng nhất.","Vị trí địa lý là điều kiện thuận lợi, không phải nguồn lực quyết định."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.4 (Vấn đề con người trong sự nghiệp cách mạng ở Việt Nam); Văn kiện Đại hội VIII trở đi","c":5,"v":"khớp","id":"dv-V.18","p":5,"t":"Trắc nghiệm"},
{"q":"Theo quan điểm mácxít, quần chúng nhân dân giữ vai trò quyết định lịch sử trước hết vì họ là:","o":["Lực lượng sản xuất cơ bản","Những người có học vấn cao nhất","Người nắm giữ quyền lực nhà nước","Những cá nhân kiệt xuất, thiên tài"],"a":[0],"e":"Giáo trình: yếu tố căn bản và quyết định của lực lượng sản xuất là quần chúng nhân dân lao động — «lực lượng cơ bản của xã hội sản xuất», trực tiếp tạo ra của cải vật chất; đồng thời là động lực của các cuộc cách mạng và người sáng tạo văn hóa tinh thần.","w":["","Quần chúng không phải những người có học vấn cao nhất.","Quyền lực nhà nước thường nằm trong tay giai cấp thống trị, không phải lý do quần chúng quyết định lịch sử.","Cá nhân kiệt xuất là lãnh tụ, không phải quần chúng."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.3 (b)","c":5,"v":"khớp","id":"dv-V.19","p":5,"t":"Trắc nghiệm"},
{"q":"\"Tính cách con người do gen quyết định hoàn toàn, môi trường xã hội không có vai trò gì.\" Theo quan điểm mácxít, nhận định này:","o":["Tuyệt đối hóa mặt sinh học, bỏ qua mặt xã hội","Đánh giá đúng bản chất của con người","Đề cao quá mức vai trò của xã hội","Đúng, vì con người trước hết là một thực thể sinh học"],"a":[0],"e":"Con người là thực thể sinh học – xã hội: mặt sinh học là tiền đề, mặt xã hội quy định bản chất. Cho rằng gen quyết định hoàn toàn tính cách là tuyệt đối hóa mặt sinh học, bỏ qua mặt xã hội.","w":["","Nhận định phiến diện, không đúng bản chất con người.","Ngược lại, nhận định phủ nhận vai trò của xã hội.","Mặt sinh học chỉ là tiền đề; bản chất con người do mặt xã hội quy định."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.1 (Khái niệm con người và bản chất con người)","c":5,"v":"khớp","id":"dv-V.20","p":5,"t":"Tìm lỗi lập luận"},
{"q":"\"Lịch sử là lịch sử của các vị anh hùng; nhân dân chỉ đi theo.\" Lỗi của quan điểm này là:","o":["Tuyệt đối hóa cá nhân, xem nhẹ quần chúng","Đánh giá đúng vai trò của quần chúng nhân dân","Phủ nhận hoàn toàn vai trò của lãnh tụ","Đề cao tính tất yếu khách quan của lịch sử"],"a":[0],"e":"Quần chúng nhân dân là chủ thể sáng tạo chân chính ra lịch sử. Anh hùng, lãnh tụ có vai trò quan trọng nhưng không thay thế được vai trò quyết định của quần chúng; coi «nhân dân chỉ đi theo» là tuyệt đối hóa cá nhân.","w":["","Quan điểm này hạ thấp vai trò quần chúng.","Quan điểm này tuyệt đối hóa, chứ không phủ nhận, vai trò lãnh tụ.","Quan điểm này bỏ qua tính tất yếu khách quan của lịch sử."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.3 (b)","c":5,"v":"khớp","id":"dv-V.21","p":5,"t":"Tìm lỗi lập luận"},
{"q":"\"Nếu không có lãnh tụ thiên tài thì cách mạng không bao giờ xảy ra.\" Theo quan điểm duy vật lịch sử, nhận định này sai vì:","o":["Lãnh tụ xuất hiện do nhu cầu của lịch sử","Lãnh tụ hoàn toàn không có vai trò gì trong lịch sử","Cách mạng xã hội chỉ là sản phẩm của sự ngẫu nhiên","Lãnh tụ do số phận định sẵn"],"a":[0],"e":"Giáo trình: lãnh tụ là sản phẩm của thời đại, của phong trào; quần chúng và phong trào tạo nên lãnh tụ và điều kiện để lãnh tụ xuất hiện. Cách mạng nổ ra từ mâu thuẫn khách quan; khi lịch sử đặt ra nhiệm vụ thì sẽ xuất hiện người đáp ứng.","w":["","Lãnh tụ có vai trò quan trọng (thúc đẩy hoặc kìm hãm), không phải không có vai trò gì.","Cách mạng có nguồn gốc khách quan, không phải ngẫu nhiên.","«Số phận định sẵn» là quan điểm định mệnh, duy tâm."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.3 (b)","c":5,"v":"khớp","id":"dv-V.22","p":5,"t":"Tìm lỗi lập luận"},
{"q":"\"Muốn hiểu một người, chỉ cần nghe những gì họ tự nói về mình.\" Theo quan điểm mácxít, cách hiểu này thiếu sót vì:","o":["Bỏ qua thực tiễn và các quan hệ xã hội của họ","Đề cao quá mức vai trò của lao động sản xuất vật chất","Cho rằng con người có bản chất xã hội","Coi trọng mặt sinh học của con người"],"a":[0],"e":"Con người bộc lộ bản chất qua hoạt động thực tiễn và các quan hệ xã hội. Giáo trình: đánh giá phẩm chất con người phải qua hành động thực tiễn, không chỉ qua lời tự nhận xét.","w":["","Cách hiểu này không đề cập lao động sản xuất.","Cách hiểu này bỏ qua, chứ không khẳng định, bản chất xã hội.","Cách hiểu này không đề cập mặt sinh học."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.1 (Khái niệm con người và bản chất con người)","c":5,"v":"khớp","id":"dv-V.23","p":5,"t":"Tìm lỗi lập luận"},
{"q":"Một số ứng dụng được thiết kế để người dùng lướt không ngừng, khiến họ mất thời gian học tập và các mối quan hệ thật. Theo góc nhìn của Mác, hiện tượng này có nét tương đồng với:","o":["Con người bị chính sản phẩm của mình chi phối","Con người được phát triển tự do và toàn diện hơn","Bản chất sinh học quyết định toàn bộ hành vi","Quần chúng sáng tạo ra lịch sử"],"a":[0],"e":"Tha hóa là khi sản phẩm do con người tạo ra quay lại chi phối, thống trị con người. Ứng dụng «lướt vô tận» do con người làm ra nhưng lại chiếm thời gian, làm nghèo các quan hệ thật của người dùng — nét tương đồng với hiện tượng tha hóa.","w":["","Ngược lại: người dùng mất thời gian phát triển bản thân.","Hành vi này do thiết kế sản phẩm và môi trường xã hội, không do bản chất sinh học quyết định.","Không liên quan tới vai trò quần chúng trong lịch sử."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.2 (Hiện tượng tha hóa con người và vấn đề giải phóng con người)","c":5,"v":"khớp","id":"dv-V.24","p":5,"t":"Tình huống thời sự"},
{"q":"Trí tuệ nhân tạo có thể viết bài, vẽ tranh. Theo quan điểm mácxít về con người, điều gì vẫn phân biệt căn bản con người với AI?","o":["Con người là chủ thể thực tiễn, quan hệ xã hội","AI hoàn toàn không thể xử lý ngôn ngữ của con người","Con người luôn tính toán nhanh hơn mọi máy móc","Con người không cần học hỏi vẫn biết mọi thứ"],"a":[0],"e":"Theo Mác, bản chất con người là tổng hòa các quan hệ xã hội, hình thành qua lao động và thực tiễn. AI là sản phẩm của lao động con người (giáo trình gọi là «người máy thông minh» giúp khắc phục hạn chế của con người), không phải chủ thể thực tiễn và quan hệ xã hội.","w":["","Sai thực tế: AI xử lý được ngôn ngữ.","Sai thực tế: máy tính toán nhanh hơn con người.","Con người phải học hỏi qua thực tiễn; nhận thức là quá trình."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.1 (Khái niệm con người và bản chất con người); Ch.2, mục I (bản chất của ý thức)","c":5,"v":"khớp","id":"dv-V.25","p":5,"t":"Tình huống thời sự"},
{"q":"Nhà nước đầu tư mạnh cho giáo dục, đào tạo nhân lực số để đón làn sóng công nghệ. Chính sách này thể hiện quan điểm:","o":["Con người là nguồn lực quan trọng nhất","Tài nguyên thiên nhiên quyết định sự phát triển","Công nghệ thay thế hoàn toàn vai trò con người","Phát triển kinh tế không cần đến giáo dục"],"a":[0],"e":"Đầu tư cho giáo dục, đào tạo nhân lực số là đầu tư cho nguồn lực con người — nguồn lực quan trọng nhất theo quan điểm của Đảng; đồng thời thể hiện người lao động là yếu tố quyết định của lực lượng sản xuất.","w":["","Chính sách hướng vào con người, không phải tài nguyên thiên nhiên.","Công nghệ không thay thế hoàn toàn con người; con người tạo ra và sử dụng công nghệ.","Ngược lại: giáo dục là nền tảng phát triển kinh tế."],"s":"[GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021)](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf), Ch.3, mục V.4 (Vấn đề con người trong sự nghiệp cách mạng ở Việt Nam); Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":5,"v":"khớp","id":"dv-V.26","p":5,"t":"Tình huống thời sự"}
]);
